INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (53, 'agilent', 'Agilent', 'D+Q', 'https://www.dutscher.com/search?initialFilters=brand:Agilent', NULL, 'yes', NULL, NULL, 'https://www.agilent.com', 'prior', 'USA', 'ארה"ב', 'Santa Clara, California', NULL, 1999, 'Diversified analytical & life-science instruments', NULL, 18100, 2025, 'company', 'prior', 6950, 'USD 6.95 billion', 'FY2025 (ended 31 Oct 2025)', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Agilent''s own live Israel contact page (agilent.com/en/contact-us/israel) still lists Eldan Electronic Instruments Ltd., Petach Tikva, as its authorized distributor with phone and e-mail; a second Agilent partner page gives an Eldan contact address. A search restricted to eldan.biz returned only SEC filings (search-engine quirk), but Eldan pages seen in other searches (2014 ILANIT listing, 2017 Seahorse users meeting) are consistent. No direct Agilent office in Israel surfaced. Agilent''s own Israel contact page lists Eldan Electronic Instruments (Kiryat Gat / Petah Tikva, Neopharm group) as its authorised distributor; Eldan''s site says it has represented Agilent for over four decades. Whether Agilent also has a direct office for genomics/cell analysis (BioTek) remains to be checked.', '+1 408-345-8886 / +1 877-424-4536', 'contact_us@agilent.com', '5301 Stevens Creek Blvd., Santa Clara, CA 95051, USA', NULL, 'https://reporting.chem.agilent.com/cdc/bottom_page.html', NULL);
INSERT INTO products VALUES (53, 1, 'Agilent 1290 Infinity III LC', 'flagship UHPLC liquid chromatography system', 'prior', NULL);
INSERT INTO products VALUES (53, 2, 'Agilent 8890 GC / 7010 Triple Quad GC/MS', 'gas chromatograph and GC-MS/MS systems', 'prior', NULL);
INSERT INTO products VALUES (53, 3, 'Agilent BioTek Cytation', 'cell imaging multimode microplate reader', 'prior', NULL);
INSERT INTO israel_entities VALUES (53, 'Eldan Electronic Instruments Ltd. (Neopharm group)', 'אלדן', 'distributor', 'Agilent authorised distributor for Israel (chromatography, spectroscopy, mass spectrometry, lab products, cell analysis); Petach Tikva, tel. +972-3-9371111, info@eldan.biz, per Agilent''s live Israel contact page', 'https://www.eldan.biz', '+972-3-937-1111', 'info@eldan.biz', '6 Hashiloach Street, P.O. Box 7641, Petach Tikva 49170', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.agilent.com/en/contact-us/israel');
INSERT INTO sources VALUES (53, 'https://www.dutscher.com/search?initialFilters=brand:Agilent');
