INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (99, 'analytik jena', 'Analytik Jena', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/analytik-jena', NULL, NULL, NULL, 'https://www.analytik-jena.com', 'prior', 'Germany', 'גרמניה', 'Jena', 'Endress+Hauser Group', 1990, 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 'company', 1000, 2024, 'estimate', 'prior', 200, 'EUR ~180 million (trade estimate)', '2024 (estimate)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] All three distributor pages are live: Lifegene''s Biometra TAdvanced, TOne and TRobot II pages describe them as premium PCR instruments from Analytik Jena; Tamar Laboratory Supplies'' qTOWER³ page and its ''PCR instruments from Biometra'' project page are current; Lumitron''s About page describes UVP as a part of Analytik Jena. analytik-jena.com''s partners page lists global distribution and service partners by location but the Israel entry was not exposed in snippets, so the chemical-analysis portfolio (AAS, ICP, TOC) still has no confirmed Israeli channel. Three Israeli distributors carry Analytik Jena life-science lines on their own sites: Lifegene (Biometra TOne and TAdvanced thermal cyclers), Tamar Laboratory Supplies (qTOWER³ real-time PCR) and Lumitron (UVP bio-imaging, described as ''a part of Analytik Jena''). The BioFindly directory also lists one Israeli representative for Analytik Jena tied to qPCR/spectrophotometers (text garbled in the snippet). The chemical-analysis portfolio (AAS, ICP-OES/MS, TOC, mercury) has no confirmed Israeli channel: analytik-jena.com''s partner finder did not expose an Israel entry in search snippets.', '+49 3641 77-70', 'info@analytik-jena.com', 'Konrad-Zuse-Str. 1, 07745 Jena, Germany', 'https://analytik-jena.com/contact', 'https://www.analytik-jena.fr/en/print/company/career/contact.html', 'Q136196');
INSERT INTO products VALUES (99, 1, 'PlasmaQuant 9100 / PlasmaQuant MS', 'ICP-OES and ICP-MS spectrometers', 'prior', NULL);
INSERT INTO products VALUES (99, 2, 'contrAA 800', 'high-resolution continuum-source AAS', 'prior', NULL);
INSERT INTO products VALUES (99, 3, 'multi N/C series', 'TOC/TNb analyzers', 'prior', NULL);
INSERT INTO israel_entities VALUES (99, 'Lifegene', NULL, 'distributor', 'Biometra thermal cyclers (TAdvanced, TOne, TRobot II) described on Lifegene''s live pages as premium PCR instruments from Analytik Jena', 'https://www.lifegene.co.il', '+972 8-644-4314', 'info@lifegene.co.il', '4 Ha''maayan St., Modi''in 7171101 (directory lists Modi''in; other sources say Mevo Horon – verify)', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.lifegene.co.il/biometra_tadvanced_pcr');
INSERT INTO israel_entities VALUES (99, 'Tamar Laboratory Supplies', NULL, 'distributor', 'qTOWER³ real-time PCR thermal cycler (live product page) and ''PCR instruments from Biometra'' (live project page)', 'https://tamar.co.il', '+972 2-533-6070 (also 02-579-9777)', NULL, 'HaAla St., Mevaseret Zion 90805', NULL, 2026, 'current', 'prior_research', NULL, 'https://tamar.co.il/qtower%C2%B3');
INSERT INTO israel_entities VALUES (99, 'Lumitron', 'לומיטרון', 'distributor', 'UVP bio-imaging systems - Lumitron''s live About page describes UVP as a part of Analytik Jena', 'https://www.lumitron.co.il', '+972 52-525-6287', NULL, '17 Hamiflasim St., Petah Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.lumitron.co.il/about-us/');
