INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (108, 'anton paar', 'Anton Paar', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Anton+Paar', 'https://www.thomassci.com/browse-by/suppliers/anton-paar', NULL, NULL, NULL, 'https://www.anton-paar.com', 'prior', 'Austria', 'אוסטריה', 'Graz', 'Anton Paar Group AG (owned by the charitable Santner Foundation)', 1922, 'Diversified analytical & life-science instruments', NULL, 4500, 2025, 'company', 'prior', 692, 'EUR 629 million', 'FY2025', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Prime Lab''s live home page still lists Anton Paar rheometers, density meters and SAXS systems among its products (the page is about 2.6 years old per the search index), keeping it as the distributor-side evidence. anton-paar.com exposes no Israel subsidiary or distributor in snippets (35 subsidiaries, 30+ distribution partners, contact via web form), so exclusivity and full product scope remain stated by the distributor only. Prime Lab Scientific Instruments Ltd. (Kfar Saba) lists Anton Paar GmbH among its partner manufacturers on its own site, hosts an Anton Paar SAXS product page, and describes itself as the local partner/distributor offering import, installation, IQ/OQ/PQ, calibration and after-sales service. The BioFindly directory independently names Prime Lab as the single Israeli representative handling sales, service and quotes for Anton Paar. Not cross-checked on anton-paar.com (search budget), so exclusivity and the full product scope are stated by the distributor and a directory rather than by the manufacturer.', '+43 316 257-0', NULL, 'Anton-Paar-Straße 20, 8054 Graz, Austria', NULL, 'https://fluidhandlingpro.com/manufacturers/anton-paar-gmbh/', NULL);
INSERT INTO products VALUES (108, 1, 'DMA density meters (e.g. DMA 5000 M)', 'laboratory density & concentration measurement', 'prior', NULL);
INSERT INTO products VALUES (108, 2, 'MCR rheometer series (e.g. MCR 702e)', 'rotational & oscillatory rheometers', 'prior', NULL);
INSERT INTO products VALUES (108, 3, 'Multiwave 5000 / 7000', 'microwave sample digestion systems', 'prior', NULL);
INSERT INTO israel_entities VALUES (108, 'Prime Lab Scientific Instruments Ltd.', 'פריים לאב', 'distributor', 'Anton Paar instruments (rheometers, density meters, SAXS) listed on Prime Lab''s live home page (page about 2.6 years old per the search index); import, installation, IQ/OQ/PQ, calibration and after-sales service per the distributor; not listed on anton-paar.com in snippets', 'https://primelab.co.il', NULL, NULL, NULL, NULL, 2026, 'current', 'prior_research', NULL, 'https://primelab.co.il/');
INSERT INTO sources VALUES (108, 'https://www.dutscher.com/search?initialFilters=brand:Anton+Paar');
