INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (150, 'azenta life sciences', 'Azenta Life Sciences (formerly 4titude)', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/azenta-life-sciences', NULL, NULL, NULL, 'https://www.azenta.com', 'prior', 'USA', 'ארה"ב', 'Burlington, Massachusetts', NULL, 1978, 'Lab refrigeration & cold storage', NULL, 2700, 2025, 'estimate', 'prior', 594, 'USD 594 million', 'FY2025 (ended 30-Sep-2025)', 'company', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: azenta.com has only a form-based distributor finder and its pages do not name an Israeli partner. HyLabs'' live ''AZENTA - GENOMICS SERVICES'' / ''AZENTA (GENEWIZ)'' pages (research and clinical categories) still offer Azenta/GENEWIZ gene synthesis, cloning, oligo pools, mutagenesis and plasmid prep, and Tamar''s live ''Represented companies'' page lists 4titude as an Azenta Life Sciences (UK) brand; the FluidX part of Tamar''s scope did not surface in this round''s snippets. Both distributor pages are live, so the relationships count as current. General search (''Azenta'' OR ''GENEWIZ'' Israel distributor/נציג/יבואן) returned only Azenta/GENEWIZ''s own pages with no Israel mention. Domain-restricted search found Tamar''s ''Represented companies'' page listing both ''Azenta Life Sciences (United Kingdom)'' and ''4titude (Azenta Life Sciences)'', plus a 4titude automatic roll heat sealer product page. No Israeli channel found for GENEWIZ genomics services (likely ordered directly online) or for automated -80 C / cryogenic sample stores; Azenta''s own where-to-buy page not fetched.', '+1 888-229-3682', NULL, '200 Summit Drive, Burlington, MA 01803, USA', NULL, 'https://www.azenta.com/global-locations', NULL);
INSERT INTO products VALUES (150, 1, 'BioStore III Cryo', 'automated LN2 cryogenic sample storage system', 'prior', NULL);
INSERT INTO products VALUES (150, 2, 'FluidX / Ziath tubes and readers', '2D-barcoded sample tubes and rack scanners', 'prior', NULL);
INSERT INTO products VALUES (150, 3, 'GENEWIZ services', 'Sanger/NGS sequencing and gene synthesis services', 'prior', NULL);
INSERT INTO israel_entities VALUES (150, 'HyLabs (Hy Laboratories Ltd.)', NULL, 'distributor', 'Azenta Life Sciences (formerly GENEWIZ) genomics services - gene synthesis, cloning, gene fragments (gBlock-type), oligo pools, site-directed mutagenesis, plasmid preparation - offered to Israeli research and clinical customers on HyLabs'' live ''AZENTA - GENOMICS SERVICES'' / ''AZENTA (GENEWIZ)'' pages', 'https://www.hylabs.co.il', '+972-8-936-6475', NULL, '8 Prof. Menakhem Plaut St., Rehovot (Prospeo lists 6 Plaut St., Rehovot 7670606)', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.hylabs.co.il/services/genewiz-genomics-services/');
INSERT INTO israel_entities VALUES (150, 'Tamar Laboratory Supplies Ltd.', 'תמר ציוד מעבדתי', 'distributor', '4titude (Azenta Life Sciences, UK) PCR/qPCR/sequencing plates, tubes, seals and benchtop sealers - listed on Tamar''s live ''Represented companies'' page and its automatic roll heat sealer page; the FluidX tube-capping line recorded earlier did not surface in this round''s snippets', 'https://www.tamar.co.il', '+972 2-533-6070 (also 02-579-9777)', NULL, 'HaAla St., Mevaseret Zion 90805', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.tamar.co.il/represented-companies/');
