INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (165, 'bd biosciences', 'BD Biosciences', 'Q', NULL, NULL, 'yes', NULL, NULL, 'https://www.bdbiosciences.com', 'prior', 'USA', 'ארה"ב', 'Milford, Massachusetts (Waters Corp.); former BD Biosciences HQ San Jose, California; BD corporate HQ Franklin Lakes, New Jersey', 'Waters Corporation (since 9 Feb 2026; previously Becton Dickinson)', 1897, 'Cell analysis (flow cytometry / cell sorting)', NULL, 8000, 2025, 'estimate', 'prior', 3400, 'USD 3.4 billion', 'CY2025E (basis used in the Jul-2025 deal announcement)', 'segment', 'prior', 'reported', 'subsidiary', 'חברה-בת בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] jobs.bd.com''s live Israel pages describe BD''s own commercial arm in Israel (direct entity since 2017, Life Science BDB/IDS and Medical units, ~400 associates) and the BD Caesarea manufacturing site, and a 2026 Israeli medical-device directory lists BD Israel at Harduf HaNehalim St 2, Caesarea with the BDBIsrael@bd.com address - the same address Waters gives for Augusta Life Sciences Israel Ltd. The Augusta entity was not re-surfaced by search but rests on Waters'' own 9-Feb-2026 transaction page. Note the BD careers text may predate the Feb-2026 separation; Lapidot''s BD listing was not re-seen in snippets. Searched BD Biosciences/BD Israel/Becton Dickinson Israel distributor/נציג/יבואן, Israeli distributor domains (BD, FACSymphony, FACSLyric, BD MAX, BACTEC), bd.com/waters.com, and the Waters-BD combination. bd.com''s Israel pages show BD''s own office and technical-service line in Caesarea, and Waters'' BD-transaction legal page (dated 9 Feb 2026) lists Augusta Life Sciences Israel Ltd., Caesarea, among the acquired SpinCo entities now wholly owned by Waters - i.e. the ex-BD Biosciences & Diagnostic Solutions business has its own Israeli entity under Waters. Waters states there are ''no changes for customers at this time'' and that BD remains legal manufacturer of certain regulated products until registrations transfer, so sales/service of FACS, BD MAX and BACTEC in Israel presumably continue from the Caesarea operation, but no page spelled out the post-combination commercial arrangement; no independent Israeli distributor for BD flow cytometers or BD diagnostics was found (Almog Diagnostic distributes competing Cytek/Miltenyi/Slingshot lines; Lapidot lists BD without product scope). Lapidot''s history page says it became BD''s local representative in 1992; whether this covers the former BD Biosciences / Diagnostic Solutions lines after the Feb-2026 Waters combination is not stated. A 2026 directory lists BD Israel (Harduf HaNehalim St. 2, Caesarea, BDBIsrael@bd.com) and names Elad Health (+972 3 769 3000) as a BD distributor; both unverified.', NULL, 'BDBIsrael@bd.com', 'Harduf HaNehalim St. 2, Caesarea, Israel', NULL, 'https://pharmchoices.com/list-of-medical-device-companies-in-israel-2/2/', NULL);
INSERT INTO products VALUES (165, 1, 'BD FACSDiscover S8', 'spectral cell sorter with real-time cell imaging', 'prior', NULL);
INSERT INTO products VALUES (165, 2, 'BD FACSymphony A5 SE / A1', 'high-parameter spectral flow cytometry analyzers', 'prior', NULL);
INSERT INTO products VALUES (165, 3, 'BD BACTEC FX, BD MAX, BD Phoenix', 'blood-culture, molecular IVD and ID/AST systems', 'prior', NULL);
INSERT INTO israel_entities VALUES (165, 'Augusta Life Sciences Israel Ltd. (Waters subsidiary, ex-BD Biosciences & Diagnostic Solutions)', NULL, 'subsidiary', 'Israeli entity of the acquired BD Biosciences & Diagnostic Solutions business (flow cytometry, BD MAX, BACTEC, Phoenix), listed by Waters among SpinCo entities wholly owned since 9 Feb 2026; Harduf HaNehalim St 2, Caesarea - the Feb-2026 Waters legal page remains the source (not re-surfaced by this round''s search)', 'https://www.waters.com', NULL, NULL, NULL, NULL, 2026, 'current', 'prior_research', NULL, 'https://www.waters.com/nextgen/us/en/about-waters/corporate-governance/legal-and-privacy-notices/bdtransaction.html');
INSERT INTO israel_entities VALUES (165, 'BD Israel (Becton Dickinson)', NULL, 'subsidiary', 'BD''s own Israeli commercial arm (direct entity since 2017, now within BD''s Central European commercial organisation) covering Life Science (BDB/IDS) and Medical units per jobs.bd.com, plus the BD Caesarea infusion-pump plant (ex-Caesarea Medical Electronics); c. 400 associates; Harduf HaNehalim St 2, Caesarea, BDBIsrael@bd.com per a 2026 directory; after the Feb-2026 separation the BDB/IDS lines belong to Waters', 'https://www.bd.com/en-il', NULL, NULL, 'Caesarea', NULL, 2026, 'current', 'prior_research', NULL, 'https://jobs.bd.com/location-israel');
INSERT INTO israel_entities VALUES (165, 'Lapidot Group (Lapidot Medical)', 'לפידות', 'distributor', 'lists BD as a business partner (''global medical technology company''); product scope not stated - likely BD Medical lines, not confirmed for Biosciences/Diagnostics', 'https://www.lapidot.com', '+972-4-6309630 / +972-74-7797836', 'customerservice@lapidot.com', '8 Hashita St., P.O. Box 3552, Caesarea Industrial Park 3088900', NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://www.lapidot.com/en/partners/');
