INSERT INTO israel_entities VALUES (168, 'Beckman Coulter (Israel) Ltd.', NULL, 'subsidiary', 'Beckman Coulter Diagnostics legal entity in Israel (2 Pekeris St., Park Tamar, Rehovot) listed under the BEC Diagnostics reporting group in Beckman Coulter''s EU data-controller list; commercial role (direct diagnostics sales/service) not established', NULL, NULL, NULL, NULL, NULL, 2026, 'new', 'prior_research', NULL, 'https://media.beckmancoulter.com/-/media/diagnostics/eu-assets/pdf/controller-list.pdf?rev=e10665d675ed4f24adf07082e61099f6&hash=DF4541DC81268F0844822FB104DF7F66');
