INSERT INTO products VALUES (189, 1, 'KBF / KBF P series', 'constant climate chambers for ICH stability testing', 'prior', NULL);
INSERT INTO products VALUES (189, 2, 'CB / CB-S series', 'CO2 incubators with hot-air sterilisation', 'prior', NULL);
INSERT INTO products VALUES (189, 3, 'FD / FED / FP series', 'drying and heating chambers (lab ovens)', 'prior', NULL);
INSERT INTO israel_entities VALUES (189, 'Labotal Scientific Equipment Ltd.', 'לבוטל ציוד מדעי', 'distributor', 'Binder incubators, drying ovens and climate/simulation chambers - Labotal''s live ''Binder'' represented-firm page (founded 1983 by Peter M. Binder), live ''Represented Firms'' page and drying-systems category', 'https://labotal.co.il', '+972 2-579-9222', 'Sales@labotal.co.il', 'Hashalom Rd., Abu Ghosh 9084500 (mail: Mevaseret Zion)', 'https://labotal.co.il/contact/', 2026, 'current', 'prior_research', NULL, 'https://labotal.co.il/firms/binder/?lang=en');
INSERT INTO sources VALUES (189, 'https://www.dutscher.com/search?initialFilters=brand:Binder');
