INSERT INTO israel_entities VALUES (190, 'Syntezza Bioscience Ltd', 'סינתזה ביוסיינס', 'distributor', 'Syntezza''s About page lists the custom genes and peptides of BioBasic among its product lines; its ISO compliance document (2020) lists Bio Basic Inc. (Markham, Ontario) as a manufacturing partner for products supplied in Israel; Syntezza''s scientist.com profile calls it the exclusive distributor in Israel of BioBasic for genes. Address: 17 Hartom Street, Har Hotzvim, Jerusalem.', 'https://www.syntezza.com', NULL, NULL, '17 Hartom St., Har Hotzvim, Jerusalem', NULL, 2026, 'current', 'manufacturer_or_press', 'search', 'https://www.syntezza.com/about/');
