INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (192, 'bio rad', 'Bio-Rad', 'Q', NULL, NULL, 'yes', NULL, NULL, 'https://www.bio-rad.com', 'prior', 'USA', 'ארה"ב', 'Hercules, California', NULL, 1952, 'Life-science instruments & reagents', NULL, 7450, 2025, 'company', 'prior', 2580, 'USD 2.58 billion', 'FY2025', 'company', 'prior', 'mixed', 'subsidiary', 'חברה-בת בישראל', 'verified', 'אומת', 2006, '[אימות עדכניות 10/2026] Bio-Rad''s own site re-confirms the Israeli subsidiary: the Israel trading-terms document names Bio-Rad Laboratories Ltd., 14 Homa Street, Rishon LeZion; the quality-certificates page covers an ISO 9001:2015 certificate for the Rishon LeZion site (sales, distribution and after-sales service; expiring 12 Nov 2026); and careers.bio-rad.com has a dedicated Israel page. Bio-Rad Haifa Ltd. (R&D) has only the 2006 acquisition/SEC-exhibit evidence. Own subsidiary confirmed. Bio-Rad''s careers site has a dedicated Israel page and job postings under ''Bio-Rad Israel Ltd'' with work location ''Bio-Rad Laboratories Ltd, Rishon Le Zion, Israel, 75655''. Bio-Rad''s SEC Exhibit 21.1 (FY2019 and FY2021 10-Ks) lists ''Bio-Rad Laboratories (Rishon), Inc.'' (f/k/a Bio-Rad Laboratories (Israel), Inc., California jurisdiction) and ''Bio-Rad Haifa Ltd.'' (Israel). A company directory (startupim) gives the Rishon LeZion address as 14 HaHoma St. and says the Israeli sales branch was established in 1991; Bio-Rad Haifa is the R&D centre created from the 2006 ProteOptics acquisition. Sources conflict on the exact legal form of the Rishon entity (Israeli ''Ltd'' vs California ''Inc.''). Direct sales via the own subsidiary is the channel; no independent distributor surfaced. Limitation: bio-rad.com contact page could not be opened (fetch tool failure) and the search budget ran out before a domain-restricted check.', NULL, NULL, 'Hahoma Street 14, Rishon LeZion, Israel', 'https://www.bio-rad.com/en-il/contact-us', 'https://slimpages.startupim.com/company_page/bio-rad-laboratories', NULL);
INSERT INTO products VALUES (192, 1, 'QX600 Droplet Digital PCR', 'ddPCR absolute nucleic-acid quantification system', 'prior', NULL);
INSERT INTO products VALUES (192, 2, 'CFX Opus Real-Time PCR', 'qPCR detection systems', 'prior', NULL);
INSERT INTO products VALUES (192, 3, 'ChemiDoc MP', 'gel and western-blot imaging system', 'prior', NULL);
INSERT INTO israel_entities VALUES (192, 'Bio-Rad Israel Ltd. (Bio-Rad Laboratories (Rishon))', 'ביו-ראד ישראל', 'subsidiary', 'direct sales & service of life-science and clinical-diagnostics products (Rishon LeZion; branch since 1991)', 'https://www.bio-rad.com', NULL, NULL, 'Netiv HaOr, Haifa', 'https://www.bio-rad.com/en-il/contact-us', NULL, NULL, 'prior_research', NULL, 'https://www.bio-rad.com/en-il/corporate/careers');
INSERT INTO israel_entities VALUES (192, 'Bio-Rad Haifa Ltd.', 'ביו-ראד חיפה', 'subsidiary', 'direct sales, distribution and after-sales service of life-science and clinical-diagnostics products plus a software design/manufacturing centre; 14 Homa (HaHoma) St., Rishon LeZion, tel. 03-963 6050 - bio-rad.com Israel trading terms, ISO 9001:2015 certificate (valid to 12 Nov 2026) and careers Israel page', 'https://www.bio-rad.com', NULL, NULL, 'Netiv HaOr, Haifa', 'https://www.bio-rad.com/en-il/contact-us', 2006, 'older_evidence', 'prior_research', NULL, 'https://www.bio-rad.com/webroot/web/pdf/general/trading_terms/AGB_IL.pdf');
