INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (246, 'brand', 'Brand', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Brand', NULL, NULL, NULL, NULL, 'https://www.brand.de', 'prior', 'Germany', 'גרמניה', 'Wertheim', NULL, 1949, 'Liquid handling & lab automation', NULL, 1000, 2025, 'parent', 'prior', 176, 'EUR ~160 million p.a.', 'c. FY2024 (undated current company brochure)', 'parent', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Re-checked on 2026-10-15 on the manufacturers'' own sites: BRAND''s live ''Sales and Consulting worldwide'' page names Yoel Naim Ltd., industrial area, Rehovot, as its distributor/service partner for Israel, while VACUUBRAND''s live ''Contact persons worldwide'' page lists Labotal Scientific Equipment (1997) Ltd., Mevaseret Zion, alongside a VACUUBRAND area sales manager for Israel. Labotal is therefore confirmed current for VACUUBRAND; its BRAND liquid-handling line (per its own 2018 news page) is not reflected on BRAND''s worldwide list, which names Yoel Naim instead. A general search for Yoel Naim returned no website or further details. The 40-domain sweep returned Labotal''s own product and news pages: a ''Brand Pipettors, New Series: Transferpette α'' page, single-channel pipettor category pages, VACUUBRAND ME 2 NT, ME 4 NT and MV-10C-EX pump pages, and a company-news page stating that Labotal is an authorised VACUUBRAND distributor for the laboratory segment and began carrying BRAND liquid-handling products in 2018. No other Israeli distributor site mentioned BRAND or VACUUBRAND. The manufacturers'' own distributor pages (brand.de, vacuubrand.com) were not searched within the budget, so exclusivity and other channels (e.g. BRAND consumables via general lab-supply houses) are unknown.', '+49 9342 808-0', 'info@brand.de', 'Otto-Schott-Str. 25, 97877 Wertheim, Germany', 'https://brand.de/en/contact/how-to-find-us', 'https://www.brand.de/en/imprint/', NULL);
INSERT INTO products VALUES (246, 1, 'Transferpette S / electronic', 'single- and multichannel air-displacement pipettes', 'prior', NULL);
INSERT INTO products VALUES (246, 2, 'Dispensette S & HandyStep', 'bottle-top dispensers and repetitive pipettes', 'prior', NULL);
INSERT INTO products VALUES (246, 3, 'BLAUBRAND volumetric glassware', 'Class A flasks, pipettes, burettes', 'prior', NULL);
INSERT INTO israel_entities VALUES (246, 'Labotal Scientific Equipment Ltd.', 'לבוטל', 'distributor', 'VACUUBRAND diaphragm and ATEX vacuum pumps - listed on VACUUBRAND''s live ''Contact persons worldwide'' page as its Israel contact (Mevaseret Zion), alongside a VACUUBRAND area sales manager for Israel; BRAND liquid handling (Transferpette S / electronic / alpha, carried since 2018 per Labotal''s own news page) is not reflected on BRAND''s worldwide sales list', 'https://labotal.co.il', '+972 2-579-9222', 'Sales@labotal.co.il', 'Hashalom Rd., Abu Ghosh 9084500 (mail: Mevaseret Zion)', 'https://labotal.co.il/contact/', 2026, 'current', 'prior_research', NULL, 'https://www.vacuubrand.com/service-advice/contact/contacts-worldwide');
INSERT INTO israel_entities VALUES (246, 'Yoel Naim Ltd.', NULL, 'distributor', 'BRAND (liquid handling, volumetric ware) distributor and service partner for Israel - named on BRAND''s live ''Sales and Consulting worldwide'' page (industrial area, Rehovot); website not found', NULL, NULL, NULL, NULL, NULL, 2026, 'new', 'prior_research', NULL, 'https://www.brand.de/en/company/sales-worldwide');
