INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (388, 'cytiva', 'Cytiva', 'D+Q', 'https://www.dutscher.com/search?initialFilters=brand:Cytiva', NULL, 'yes', NULL, NULL, 'https://www.cytivalifesciences.com', 'prior', 'USA', 'ארה"ב', 'Marlborough, Massachusetts', 'Danaher Corporation', 2020, 'Bioprocess & filtration', NULL, 16000, 2025, 'estimate', 'prior', 7300, 'USD 7.3 billion (Danaher Biotechnology segment)', 'FY2025', 'segment', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Danyel Biotech''s live site carries a ''Biacore (Cytiva)'' brand page (alongside its Cytiva page from the prior round), confirming Danyel as a current Cytiva channel. Cytiva''s own find-a-distributor page lists Israel as a country option but the partner name is not in snippets, and Cytiva''s contracting-entity table assigns Israel to Pall Austria Filter Ges.m.b.H. Lifegene (Whatman) was not re-searched. Searched generic queries (incl. ÄKTA/Whatman/Amersham), 27 Israeli distributor domains, cytivalifesciences.com and a Whatman-specific query. Danyel Biotech''s own site has a Cytiva brand page (ÄKTA pure chromatography; Biacore listed as a Cytiva supplier), so Danyel is a current Israeli channel. Cytiva''s ''find a distributor'' page lists Israel as a selectable country but the partner name was not visible in snippets, and Cytiva''s terms document lists Israel under its international contracting entity Pall Austria Filter Ges.m.b.H., i.e. direct contracts are also written from abroad. The 2009 Rhenium-for-Whatman listing could not be re-confirmed and no current Israeli Whatman/Amersham channel was found. Lifegene''s catalogue carries Whatman (Cytiva) filtration products; Danyel Biotech has Cytiva brand pages for ÄKTA and Biacore.', '+1 800-526-3593', NULL, '100 Results Way, Marlborough, MA, USA', NULL, 'https://www.gulfcoastconference.com/exhibitorDetails.php?eid=3143', NULL);
INSERT INTO products VALUES (388, 1, 'AKTA', 'protein purification chromatography systems', 'prior', NULL);
INSERT INTO products VALUES (388, 2, 'MabSelect / Capto resins', 'chromatography resins for biologics manufacturing', 'prior', NULL);
INSERT INTO products VALUES (388, 3, 'Biacore', 'surface plasmon resonance interaction analysis', 'prior', NULL);
INSERT INTO israel_entities VALUES (388, 'Danyel Biotech', NULL, 'distributor', 'Cytiva chromatography (ÄKTA) and Biacore - live ''Biacore (Cytiva)'' brand page on Danyel''s site; other Cytiva lines (Whatman, Amersham, Pall) not confirmed', 'https://www.danyel.co.il', '1-800-711-911 (also +972 8-936-6066)', NULL, '8 Hamada St., Science Park, Rehovot 7670308', 'https://www.danyel.co.il/contact-us/', 2026, 'current', 'prior_research', NULL, 'https://www.danyel.co.il/biacore-cytiva/');
INSERT INTO israel_entities VALUES (388, 'Lifegene Ltd.', 'לייפג''ין', 'distributor', 'Whatman filtration products (a Cytiva brand) sold through the Lifegene catalogue', 'https://www.lifegene.co.il', '+972 8-644-4314', 'info@lifegene.co.il', '4 Ha''maayan St., Modi''in 7171101 (directory lists Modi''in; other sources say Mevo Horon – verify)', NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://lifegene.co.il/product/puradisc-13-syringe-filter-045µm-polypropylene-100-pk/');
