INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (470, 'eppendorf', 'Eppendorf', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Eppendorf', 'https://www.thomassci.com/browse-by/suppliers/eppendorf', NULL, NULL, NULL, 'https://www.eppendorf.com', 'prior', 'Germany', 'גרמניה', 'Hamburg', NULL, 1945, 'Liquid handling & lab automation', NULL, 4125, 2025, 'company', 'prior', 1016, 'EUR 924 million', 'FY2025', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Lumitron''s live site carries a broad Eppendorf range (centrifuges, pipettes, BioFlo/BioBLU bioreactors, CellXpert incubator shakers, Eporator, micromanipulators) with hosted Eppendorf brochures, which replaces the earlier LinkedIn-only evidence. Eppendorf''s own site lists Israel in its country selector and says the Dubai regional company (Eppendorf Middle East and Africa FZ-LLC) works through local partners, but its distributor overview''s Israel entry was not visible in snippets, so manufacturer-side naming is still missing. Evidence is indirect: a Hebrew LinkedIn post (Nili Krool, Israel) announcing the Israeli launch (6 March) of the Eppendorf SpinPro 6 R centrifuge directs enquiries to Lumitron (לומיטרון), described as part of the Comtel Technologies & Engineering group (קומטל) and an importer of laboratory equipment and consumables - implying Lumitron markets Eppendorf in Israel, although the post does not state the distributorship explicitly. Eppendorf''s corporate site says it has subsidiaries in 33 countries and is represented elsewhere by distribution partners; no ''Eppendorf Israel'' subsidiary surfaced. Searched ''Eppendorf Israel distributor'' and ''אפנדורף Eppendorf נציג בישראל''. The eppendorf.com distributor/contact page and Lumitron''s own site could not be opened (fetch failure; search budget exhausted), so this needs confirmation.', '+49 40 53801-0', 'eppendorf@eppendorf.de', 'Barkhausenweg 1, 22339 Hamburg, Germany', 'https://www.eppendorf.com/us-en/company-careers/news-media/press-contact/', 'https://www.eppendorf.com/be-en/company-careers/legal/imprint/', NULL);
INSERT INTO products VALUES (470, 1, 'Eppendorf Research plus', 'manual mechanical pipettes', 'prior', NULL);
INSERT INTO products VALUES (470, 2, 'Centrifuge 5430 / 5910 Ri', 'benchtop refrigerated centrifuges', 'prior', NULL);
INSERT INTO products VALUES (470, 3, 'epMotion', 'automated liquid-handling workstations', 'prior', NULL);
INSERT INTO israel_entities VALUES (470, 'Lumitron Ltd. (Comtel Technologies & Engineering group)', 'לומיטרון', 'distributor', 'Eppendorf importer/distributor - live Lumitron product pages for Eppendorf centrifuges (5910 Ri, MiniSpin), pipettes (Multipette M4), bioreactors (BioFlo 120, BioBLU), shakers/incubators (CellXpert CS220, Innova S44i), Eporator and micromanipulators', 'https://www.lumitron.co.il', '+972 52-525-6287', NULL, '17 Hamiflasim St., Petah Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.lumitron.co.il/products/bioflo120-bioreactor-fermenter-2/?lang=en');
