INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (477, 'esco', 'Esco', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Esco', NULL, NULL, NULL, NULL, 'https://www.escolifesciences.com', 'prior', 'Singapore', 'סינגפור', 'Singapore (Changi South)', NULL, 1978, 'Biosafety cabinets & clean-air equipment', NULL, 1600, 2025, 'company', 'prior', 115, 'USD ~115 million (aggregator estimate; RocketReach gives USD 18.5M)', 'undated aggregator estimate (c. 2024)', 'estimate', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Danyel Biotech''s live Esco page still describes the full Esco controlled-environment range (Airstream and Labculture biosafety cabinets, fume hoods, incubators, CO2 incubators, ULT freezers), so Danyel remains the current Israeli channel on the distributor''s side. Esco''s own site (contact page, conditions of supply) describes region-restricted distributors and a Dubai trading office but did not show an Israel entry in snippets. No other Israeli Esco channel surfaced. A search for ''Esco biosafety cabinet'' restricted to Israeli distributor domains returned Danyel Biotech''s dedicated Esco page (danyel.co.il/esco), which describes Esco''s Life Sciences division range (biological safety cabinets, fume hoods, incubators, ULT freezers) with model families such as Airstream and Labculture; the same page surfaced again in two later .co.il-wide searches. Danyel Biotech is therefore recorded as the Israeli distributor. Esco''s own distributor locator (escolifesciences.com) was not searched within the budget, so Esco''s Medical/pharma-isolator lines may have a different Israeli channel.', '+65 6542 0833', 'mail@escolifesciences.com', '19 Changi South Street 1, Singapore 486777', 'https://www.escolifesciences.com/contact-us', 'https://careers.escolifesciences.com/about-us', NULL);
INSERT INTO products VALUES (477, 1, 'Airstream Class II (Gen 3)', 'biological safety cabinets', 'prior', NULL);
INSERT INTO products VALUES (477, 2, 'CelCulture', 'CO2 incubators', 'prior', NULL);
INSERT INTO products VALUES (477, 3, 'Isoclean / Streamline isolators', 'aseptic and containment isolators', 'prior', NULL);
