INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (552, 'gilson', 'Gilson Co. Inc.', 'D+T+Q', 'https://www.dutscher.com/search?initialFilters=brand:Gilson', 'https://www.thomassci.com/browse-by/suppliers/gilson', 'yes', NULL, NULL, 'https://www.gilson.com', 'prior', 'USA', 'ארה"ב', 'Middleton, Wisconsin', NULL, 1948, 'Liquid handling & lab automation', NULL, 800, 2024, 'estimate', 'prior', 200, 'USD ~200 million (trade estimate; private)', '2024 (estimate)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: gilson.com''s ''Worldwide Distributors'' page offers a country lookup but no Israeli partner appears in any snippet. A search restricted to agentek.co.il and lifegene.co.il returned only Lifegene pages: a dedicated ''פיפטורים Gilson'' page, a Gilson pipette category, PIPETMAN G/L/M and NEO listings, Diamond tips and the PlateMaster P220, so Lifegene''s Gilson channel is current; Agentek''s earlier vendors-list entry did not resurface and is kept as older evidence only. The recorded Lifegene website/scope fields were swapped in the source row and have been corrected. Searched ''"Gilson" PIPETMAN Israel distributor/נציג/יבואן'', Hebrew ''גילסון פיפטות יבואן'', the 29 Israeli distributor domains and gilson.com. Gilson''s site says it sells through distribution partners in many countries via a country lookup on its ''Worldwide Distributors'' page, but no snippet names an Israeli partner, and no Israeli distributor site returned a Gilson brand page (Ornat''s pipettes category and Tamar''s ''Pipetman-compatible tips'' page appeared, neither evidencing representation). Result: no Israeli entity identified; the manufacturer''s country selector probably lists one but could not be read through search snippets. Agentek''s own vendors page (agentek.co.il/vendors) lists the brand among the manufacturers it represents in Israel (seen in a search excerpt; the manufacturer''s own distributor page was not opened). Lifegene''s own site has Gilson brand and category pages (PIPETMAN Classic/Neo, PLATEMASTER); Agentek''s vendors list also names Gilson, so there appear to be two Israeli channels.', '+1 608-836-1551', NULL, '3000 Parmenter Street, P.O. Box 620027, Middleton, WI 53562-0027, USA', 'https://gmlh.gilson.com/GMLHSV/services-and-support/contact.html', 'https://gmlh.gilson.com/GMLHSV/services-and-support/contact.html', NULL);
INSERT INTO products VALUES (552, 1, 'PIPETMAN L / G / P', 'manual air-displacement micropipettes', 'prior', NULL);
INSERT INTO products VALUES (552, 2, 'PLC 2050 / 2250 purification systems', 'preparative HPLC / flash purification', 'prior', NULL);
INSERT INTO products VALUES (552, 3, 'GX-271 / GX-274 ASPEC', 'liquid-handling and SPE automation platforms', 'prior', NULL);
INSERT INTO israel_entities VALUES (552, 'Agentek (1987) Ltd.', 'אגנטק', 'distributor', 'Gilson liquid handling (per Agentek vendors list)', 'https://agentek.co.il', '+972 9-965-7000', NULL, 'Greenwork Yakum Business Park, Yakum 6097200', 'https://agentek.co.il/contact/', NULL, 'older_evidence', 'prior_research', NULL, 'https://agentek.co.il/vendors/');
INSERT INTO israel_entities VALUES (552, 'Lifegene Ltd.', 'לייפג''ין', 'distributor', 'Gilson PIPETMAN G/L/M/M Connected and NEO pipettes, multichannel pipettes, PIPETMAN DIAMOND tips and PlateMaster P220 - Lifegene''s live ''פיפטורים Gilson'' page, Gilson product category and product pages', 'https://www.lifegene.co.il', '+972 8-644-4314', 'info@lifegene.co.il', '4 Ha''maayan St., Modi''in 7171101 (directory lists Modi''in; other sources say Mevo Horon – verify)', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.lifegene.co.il/gilson_pipettes');
