INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (590, 'hanna instruments', 'Hanna Instruments', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/hanna-instruments', NULL, NULL, NULL, 'https://www.hannainst.com', 'prior', 'USA', 'ארה"ב', 'Woonsocket, Rhode Island', NULL, 1978, 'Water & electrochemical analysis', NULL, 1500, 2024, 'estimate', 'prior', 150, 'USD ~150 million (trade estimate; private)', '2024 (estimate)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Changed: Hanna''s own live Israel page names Mercury (mercury-ltd.co.il, Gadot Chemicals Group since 2022) as its distributor, with the partnership active since 2023, which settles the official importer question the earlier record left open; Mercury is added as a new entity. Medent remains a current reseller on the strength of its live Hanna product pages and partners page. BioAnalytics and Cannadepot were not re-checked within the search budget and are kept as older evidence. Hanna products are sold in Israel by Medent Scientific Instruments (מדנט מכשור מדעי; an extensive Hanna catalogue of pH/EC/TDS meters, electrodes and photometers on its own site), BioAnalytics (bioanalytics.co.il; Hanna pool/spa and food pH testers) and the online retailer Cannadepot (Hanna portable testers). Hanna''s own ''Find My Hanna'' page lists Israel, but the local contact was not visible in search snippets, so the official importer or exclusive distributor is not established; the companies above may be resellers of that importer.', '+1 401-765-0048', 'intsales@hannainst.com; sales@hannainst.com (US sales/technical service office, Smithfield RI)', '584 Park East Drive, Highland Industrial Park, Woonsocket, RI 02895, USA', 'https://hannainst.com/contact-us/', 'https://hannainst.ec/catalogo/14', NULL);
INSERT INTO products VALUES (590, 1, 'HI931 / HI932', 'automatic potentiometric titrators', 'prior', NULL);
INSERT INTO products VALUES (590, 2, 'edge (HI2020)', 'benchtop/portable pH, EC and DO meter', 'prior', NULL);
INSERT INTO products VALUES (590, 3, 'HI83300 series & Checker HC', 'multiparameter photometers and handheld colorimeters', 'prior', NULL);
INSERT INTO israel_entities VALUES (590, 'Medent Scientific Instruments', 'מדנט מכשור מדעי', 'distributor', 'Hanna pH/mV/ISE benchtop meters (HI5222), portable pH/EC meters (HI99121, HI8733), photometers (HI97721, HI97735), electrodes (HI1083B, HI1131B, HI3131B, FC2020) and the HI901W wine titrator on live Hebrew product pages, with a 1-year warranty; Medent''s live ''Our Partners'' page lists Hanna Instruments USA. Reseller; not named by Hanna as its distributor', 'https://www.medent.co.il', '+972 72-395-0508 (sales); +972 8-683-6306 (service)', 'info@medent.co.il', '110 Mordei HaGetaot St., Beer Sheva 8420643', 'https://www.medent.co.il/scientific.equipment/%D7%A6%D7%95%D7%A8-%D7%A7%D7%A9%D7%A8/', 2026, 'current', 'prior_research', NULL, 'https://www.medent.co.il/en/project/page/2/');
INSERT INTO israel_entities VALUES (590, 'BioAnalytics', NULL, 'distributor', 'Hanna pool/spa and food (bread/dough) pH testers', 'https://www.bioanalytics.co.il', '+972-72-242-9555', NULL, '29 Omarim St. (listed as "29''th Omarim"), Omer 84965', NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://www.bioanalytics.co.il/products/hannah-pool-line-ph-tester-according-to-6223-israeli-standard/');
INSERT INTO israel_entities VALUES (590, 'Cannadepot', NULL, 'distributor', 'online retailer; Hanna portable pH/EC/TDS testers', 'https://cannadepot.co.il', NULL, NULL, NULL, NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://cannadepot.co.il/product-category/%D7%9E%D7%93%D7%99%D7%93%D7%94-%D7%95%D7%91%D7%A7%D7%A8%D7%94/hanna-instruments-%D7%9E%D7%9B%D7%A9%D7%99%D7%A8%D7%99%D7%9D-%D7%94%D7%90%D7%A0%D7%94/');
INSERT INTO israel_entities VALUES (590, 'Mercury (mercury-ltd.co.il; part of Gadot Chemicals Group)', 'מרקורי', 'distributor', 'Hanna Instruments'' official distributor for Israel per Hanna''s own live Israel page (pages.hannainst.com/israel): partnership listed as active since 2023; Mercury joined Gadot Chemicals Group in 2022 and offers Israeli research and industry a broad basket of products meeting regulatory requirements; sales and product contacts are on the mercury-ltd.co.il domain', 'https://www.mercury-ltd.co.il', '+972 3-938-7164', NULL, '12 Ha''avoda St., P.O. Box 159, Rosh Ha''ayin', 'https://eng.mercury-ltd.co.il/about_us', 2026, 'new', 'prior_research', NULL, 'https://pages.hannainst.com/israel');
