INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (603, 'hettich', 'Hettich', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Hettich', NULL, NULL, NULL, NULL, 'https://www.hettichlab.com', 'prior', 'Germany', 'גרמניה', 'Tuttlingen', 'Bregal Unternehmerkapital (investor via 2024 growth partnership; stake size not verified)', 1904, 'Centrifuges', NULL, 500, 2025, 'company', 'prior', 110, '> EUR 100 million', 'FY2023', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Upgraded from the 2016 archive page: Hettich''s own live contact page names Eldan Electronic Instruments Co. Ltd. (Neopharm Building, Petach-Tikva) as its Israel contact, and Eldan''s live laboratory-instruments page lists Hettich benchtop, floor-standing and high-performance centrifuges plus HettCube/CO2 incubators. Both sides therefore confirm the relationship as current. The same Hettich page lists Arcomed (Ramallah) separately for Palestine. Search ''"Hettich" centrifuge Israel distributor'' returned Eldan''s own page ''Hettich Lab Technology'' (https://eldan.biz/?p=9327, Neopharm Group) stating ''Eldan offers in Israel the whole product range by Hettich''; the page sits in Eldan''s 2016 archive (eldan.biz/2016/page/3), so the relationship is documented as of 2016 and its current status should be re-confirmed. Not cross-checked on hettichlab.com (page could not be opened). A Sigma-Aldrich Israel catalogue entry for a Hettich item also appeared but is a global catalogue listing, not distribution evidence. Hebrew search ''Hettich צנטריפוגה יבואן ישראל אלדן'' added nothing. Tooling caveat: in this session WebFetch failed with DNS errors on every host, direct HTTPS was policy-blocked by the proxy, and the shared per-turn WebSearch budget ran out before .co.il-restricted and manufacturer-site-restricted searches could run. Steps (b) manufacturer distributor page and (c) Israeli distributor site check were therefore NOT completed; only step (a) searches were done.', '+49 7461 705-0', 'info@hettichlab.com', 'Föhrenstraße 12, 78532 Tuttlingen, Germany', 'https://www.hettichlab.com/contact/', 'https://www.hettichlab.com/imprint', NULL);
INSERT INTO products VALUES (603, 1, 'UNIVERSAL 320 / 320 R', 'benchtop laboratory centrifuge', 'prior', NULL);
