INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (626, 'huber', 'Huber USA', 'T+Q', NULL, 'https://www.thomassci.com/browse-by/suppliers/huber-usa', 'yes', NULL, NULL, 'https://www.huber-online.com', 'prior', 'Germany', 'גרמניה', 'Offenburg', NULL, 1968, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', NULL, 480, 2023, 'company', 'prior', 83, 'EUR ~75 million (trade estimate; private)', '2024 (estimate)', 'estimate', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] S.L. Moran''s live site re-confirms the Huber relationship: it hosts Huber''s 2025/2026 general catalogue (uploaded September 2025) and lists Ministat/Unistat units in its heating/cooling-bath category and Huber on its suppliers page. Huber''s own locations page (huber-online.com) lists subsidiaries only and no Israeli distributor was visible, so the manufacturer-side listing is not confirmed. Master-Cold was not re-checked and stays as a low-confidence older entry. A .co.il-wide search for ''Huber Unistat Ministat'' found S.L. Moran (ש.ל מורן, Jerusalem) hosting the Huber ''Inspired by temperature'' general catalogue 2025/2026 (uploaded September 2025) and listing Huber circulation baths and chillers in its heating/cooling-bath category, and a follow-up search restricted to slmoran.co.il confirmed those pages plus a Huber CS-Chiller brochure, so S.L. Moran is recorded as the Israeli distributor. Master-Cold (master-cold.co.il) lists a Ministat 230 and a used Unistat CC and is recorded as a secondary reseller with low confidence. Huber''s own site (huber-online.com) returned only its generic locations/contact pages with no Israel entry visible, and the earlier distributor-domain search found only a Labotal reactor article mentioning Huber in passing.', '+49 781 9603-0', 'info@huber-online.com', 'Werner-von-Siemens-Straße 1, 77656 Offenburg, Germany', 'https://huber-online.com/en/company/locations', 'https://huber-online.com/en/company/locations', NULL);
INSERT INTO products VALUES (626, 1, 'Unistat', 'highly dynamic temperature control systems (-125 to +425 C)', 'prior', NULL);
INSERT INTO products VALUES (626, 2, 'Unichiller', 'recirculating chillers', 'prior', NULL);
INSERT INTO products VALUES (626, 3, 'Ministat / Petite Fleur / CC series', 'compact bath and circulation thermostats', 'prior', NULL);
INSERT INTO israel_entities VALUES (626, 'S.L. Moran Ltd.', 'ש.ל מורן', 'distributor', 'Huber circulation baths, thermostats and chillers (Ministat 230 variants, Unistat 405 etc.) - S.L. Moran''s live heating/cooling-bath category and suppliers page; the site hosts the Huber general catalogue 2025/2026 (uploaded September 2025) and the CS-Chiller brochure', 'https://slmoran.co.il', '+972 74-702-9898', NULL, 'Shatner Center 7, Givat Shaul, Jerusalem', NULL, 2026, 'current', 'prior_research', NULL, 'https://slmoran.co.il/products_cat/%D7%90%D7%9E%D7%91%D7%98%D7%99-%D7%97%D7%99%D7%9E%D7%95%D7%9D-%D7%A7%D7%99%D7%A8%D7%95%D7%A8-%D7%A1%D7%99%D7%A8%D7%A7%D7%95%D7%9C%D7%98%D7%95%D7%A8/');
