INSERT INTO products VALUES (696, 2, 'JSM-IT800 / JSM-7900F', 'field-emission scanning electron microscopes', 'prior', NULL);
INSERT INTO products VALUES (696, 3, 'JNM-ECZ Luminous (ECZL)', 'NMR spectrometer series', 'prior', NULL);
