INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (720, 'kimble', 'Kimble', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Kimble', NULL, NULL, NULL, NULL, 'https://www.dwk.com', 'prior', 'Germany', 'גרמניה', 'Mainz (sources also cite Wertheim; US headquarters Millville, New Jersey)', 'One Equity Partners (portfolio company)', 2017, 'Labware & consumables (plastic & glass)', NULL, 1800, 2025, 'company', 'prior', 106, 'USD 105.7 million', 'FY2023', 'estimate', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'partial', 'חיפוש חלקי', 2026, 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: dwk.com''s ''Global Distributors'' locator is location based and no Israeli distributor appears in any snippet. Danyel Biotech''s live SciLabware brand page still presents SciLabware as ''a DWK Life Sciences company'' and lists the Pyrex, Quickfit, MBL, Azlon, Ramboldi and WHEATON lines, so Danyel''s SciLabware/Wheaton channel is current; no Israeli site naming DURAN or KIMBLE surfaced, so the channel for those lines remains unknown. Danyel Biotech''s own brand page ''SciLabware - Danyel Biotech'' presents SciLabware as ''a DWK Life Sciences company'' and lists its 6,000+ products (Pyrex borosilicate and Quickfit jointed glassware, MBL volumetric ware, Azlon plasticware, Wheaton packaging and dropper bottles), so Danyel represents at least DWK''s UK SciLabware/Wheaton range in Israel. Searches for DURAN, Wheaton and Kimble across the 40 Israeli distributor domains and a Hebrew query (''DURAN בקבוקי זכוכית מעבדה יבואן ישראל'') found no Israeli site naming DURAN or KIMBLE, so the channel for those lines (possibly general lab-supply houses or VWR/Thermo catalogues) remains unidentified. DWK''s own site was not searched within the budget.', '+49 9342 802-0', NULL, 'Otto-Schott-Str. 21, 97877 Wertheim, Germany', 'https://www.dwk.com/request-a-quote', 'https://dwk.com/na/locations/wertheim-germany', NULL);
INSERT INTO products VALUES (720, 1, 'DURAN laboratory glass bottles', 'GL 45 borosilicate 3.3 bottles & lab glassware', 'prior', NULL);
INSERT INTO products VALUES (720, 2, 'WHEATON vials & serum bottles', 'glass vials, serum bottles, packaging', 'prior', NULL);
INSERT INTO products VALUES (720, 3, 'KIMBLE KIMAX glassware', 'volumetric & general laboratory glassware', 'prior', NULL);
INSERT INTO israel_entities VALUES (720, 'Danyel Biotech Ltd. (Gamida for Life group)', 'דניאל ביוטק', 'distributor', 'SciLabware (''a DWK Life Sciences company'', UK): Pyrex borosilicate and Quickfit jointed glassware, MBL volumetric ware, Azlon reusable plasticware, Ramboldi disposable plasticware and WHEATON packaging/dropper bottles - per Danyel''s live SciLabware brand page; DURAN and KIMBLE lines not shown', 'https://www.danyel.co.il', '1-800-711-911 (also +972 8-936-6066)', NULL, '8 Hamada St., Science Park, Rehovot 7670308', 'https://www.danyel.co.il/contact-us/', 2026, 'current', 'prior_research', NULL, 'https://www.danyel.co.il/scilabware/');
INSERT INTO sources VALUES (720, 'https://www.dutscher.com/search?initialFilters=brand:Kimble');
