INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (751, 'lauda', 'Lauda', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Lauda', 'https://www.thomassci.com/browse-by/suppliers/lauda', NULL, NULL, NULL, 'https://www.lauda.de', 'prior', 'Germany', 'גרמניה', 'Lauda-Königshofen', NULL, 1956, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', NULL, 600, 2025, 'company', 'prior', 110, 'EUR ~100 million (group)', 'FY2024', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] LAUDA''s own live warranty-participants page names Avni Meshulam & Son Ltd., Haifa, as its authorized sales & service partner for Israel (the same page also shows a LAUDA Ultracool/LAUDA Iberica line against Haifa, apparently a layout artefact), and LAUDA''s locations page lists Israel among countries with representatives, so Avni & Son is upgraded to a confirmed authorised partner. Medent''s live LAUDA category pages re-confirm it as a current laboratory-range channel. Citrine Solutions was not re-checked and is kept as older evidence. Medent''s own site has a ''Lauda - Germany'' manufacturer page describing LAUDA as the global leader in constant-temperature equipment plus a Hebrew product category for LAUDA baths, circulators and chillers, so Medent is the clearest Israeli distributor for the laboratory range. A .co.il-wide search also found Citrine Solutions selling LAUDA Variocool VC 1200, Ultracool UC2 and MGW MS units, and Avni & Son hosting the 2026 LAUDA Ultracool (process chiller) brochure, which suggests an industrial-side partner; both are recorded with caveats because neither page states an authorised-distributor relationship. LAUDA''s own locator (lauda.de) was not searched within the budget.', '+49 9343 503-0', 'info@lauda.de', 'Laudaplatz 1, 97922 Lauda-Königshofen, Germany', 'https://www.lauda.de/de/kontakt', 'https://lauda.de/en/imprint', NULL);
INSERT INTO products VALUES (751, 1, 'Integral', 'process thermostats for heating and cooling', 'prior', NULL);
INSERT INTO products VALUES (751, 2, 'PRO / ECO / Alpha', 'laboratory heating and cooling thermostats', 'prior', NULL);
INSERT INTO products VALUES (751, 3, 'Ultracool / Variocool', 'process circulation chillers', 'prior', NULL);
INSERT INTO israel_entities VALUES (751, 'Medent Scientific Instruments', 'מדנט מכשור מדעי', 'distributor', 'LAUDA laboratory baths, circulators and chillers - live Hebrew category ''LAUDA baths, circulators and chillers'' (chillers sub-category) and the ''Lauda - Germany'' partner page; GFL-brand water stills also listed', 'https://www.medent.co.il', '+972 72-395-0508 (sales); +972 8-683-6306 (service)', 'info@medent.co.il', '110 Mordei HaGetaot St., Beer Sheva 8420643', 'https://www.medent.co.il/scientific.equipment/%D7%A6%D7%95%D7%A8-%D7%A7%D7%A9%D7%A8/', 2026, 'current', 'prior_research', NULL, 'https://www.medent.co.il/scientific.equipment/product-category/lauda-%D7%90%D7%9E%D7%91%D7%98%D7%99%D7%9D-%D7%A1%D7%99%D7%A8%D7%A7%D7%95%D7%9C%D7%98%D7%95%D7%A8%D7%99%D7%9D-%D7%95%D7%A6%D7%99%D7%9C%D7%A8%D7%99%D7%9D/%D7%A6%D7%99%D7%9C%D7%A8%D7%99%D7%9D/');
INSERT INTO israel_entities VALUES (751, 'Citrine Solutions', 'סיטרין', 'distributor', 'reseller listing LAUDA Variocool VC 1200 and Ultracool UC2 circulation chillers and an MGW MS heating circulator (new and used lab equipment dealer; authorisation not stated)', 'https://www.citrinesolutions.co.il', NULL, NULL, NULL, NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://citrinesolutions.co.il/?c_id=30&item_id=5&module=product&p_id=444');
INSERT INTO israel_entities VALUES (751, 'Avni & Son', NULL, 'distributor', 'LAUDA''s authorised sales & service partner for Israel: LAUDA''s own live warranty-conditions ''Participants'' page lists ''Israel - Avni Meshul. & Son Ltd., Haifa - Authorized sales & service partner'' (5-year warranty programme); the site also hosts the 2026 LAUDA Ultracool process-chiller brochure. Upgraded from unverified reseller', 'https://avni-son.co.il', '+972-4-821-9989', 'info@avni-son.co.il', '101 Bar Yehuda Rd. (דרך בר יהודה 101), Nesher', 'https://avni-son.co.il/%D7%A6%D7%A8%D7%95-%D7%A7%D7%A9%D7%A8/', 2026, 'current', 'prior_research', NULL, 'https://www.lauda.de/us/warranty-conditions/participants');
INSERT INTO sources VALUES (751, 'https://www.dutscher.com/search?initialFilters=brand:Lauda');
