INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (832, 'memmert', 'Memmert', 'D+T+Q', 'https://www.dutscher.com/search?initialFilters=brand:Memmert', 'https://www.thomassci.com/browse-by/suppliers/memmert', 'yes', NULL, NULL, 'https://www.memmert.com', 'prior', 'Germany', 'גרמניה', 'Schwabach (Bavaria); second plant in Büchenbach', NULL, 1933, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', NULL, 550, 2024, 'company', 'prior', 93.2, 'EUR 84.7 million', 'FY2024', 'company', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Medent''s live product-category pages (cooled, CO2 and standard incubators, vacuum and drying ovens) still present Memmert units, so Medent remains a current Israeli channel. On the manufacturer side, Memmert''s live ''Your contact person'' page lists Israel under a Channel Sales Manager (Ilya Rumynskiy, +49 9122 925 223) and in its order-processing group, i.e. Israel is handled by channel sales from Germany through local partners; memmert.com does not name the Israeli distributor in snippets. No other Israeli Memmert channel was found. A search for ''Memmert'' restricted to Israeli lab-distributor domains returned a series of Medent (מדנט מכשור מדעי) product pages that explicitly describe the items as ''made by MEMMERT Germany'' (CO2 incubator INC108ivf, IPP/IPS cooled incubators, VO vacuum ovens, UF/UN drying ovens), so Medent is recorded as an Israeli distributor on the strength of its own site. A .co.il-wide search also found a Memmert UF260 datasheet (2017) hosted on kimron.co.il, which is a possible second reseller but is not recorded as an entity because no product or brand page was seen. Memmert''s own distributor locator (memmert.com) was not searched within the budget, so this is distributor-side evidence only; a Labotal 2026 incubator buyer''s guide mentions Memmert''s IPPeco Peltier models but Labotal is a Binder partner and was not seen offering Memmert.', '+49 9122 925-0', 'sales@memmert.com', 'Äußere Rittersbacher Straße 38, 91126 Schwabach, Germany', NULL, 'https://arablab.german-pavilion.com/en/sites/exhibitors/145084', NULL);
INSERT INTO products VALUES (832, 1, 'UN / UF series', 'universal heating and drying ovens', 'prior', NULL);
INSERT INTO products VALUES (832, 2, 'IN / IF / ICO series', 'incubators, cooled and CO2 incubators', 'prior', NULL);
INSERT INTO products VALUES (832, 3, 'HPP / ICH series', 'constant climate and stability test chambers', 'prior', NULL);
INSERT INTO israel_entities VALUES (832, 'Medent Scientific Instruments', 'מדנט מכשור מדעי', 'distributor', 'Memmert cooled incubators (IPP110 ... IPS750; 53-749 L), CO2 incubators (INC108MED, INCO246MED), vacuum ovens (VO200/VO400/VO500 incl. cooled), drying ovens (UF450, UF750, UN750) and incubators on live Hebrew product-category pages describing the units as Memmert (Germany)', 'https://www.medent.co.il', '+972 72-395-0508 (sales); +972 8-683-6306 (service)', 'info@medent.co.il', '110 Mordei HaGetaot St., Beer Sheva 8420643', 'https://www.medent.co.il/scientific.equipment/%D7%A6%D7%95%D7%A8-%D7%A7%D7%A9%D7%A8/', 2026, 'current', 'prior_research', NULL, 'https://www.medent.co.il/scientific.equipment/product-category/%D7%90%D7%99%D7%A0%D7%A7%D7%95%D7%91%D7%98%D7%95%D7%A8%D7%99%D7%9D/%D7%90%D7%99%D7%A0%D7%A7%D7%95%D7%91%D7%98%D7%95%D7%A8-%D7%9E%D7%A7%D7%95%D7%A8%D7%A8/');
