INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (835, 'merck', 'Merck', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Merck', NULL, NULL, NULL, NULL, 'https://www.sigmaaldrich.com', 'prior', 'Germany', 'גרמניה', 'Darmstadt', 'Merck KGaA', 1668, 'Life-science instruments & reagents', NULL, 62461, 2025, 'parent', 'prior', 9900, 'EUR 9.0 billion', 'FY2025', 'segment', 'prior', 'reported', 'subsidiary', 'חברה-בת בישראל', 'partial', 'חיפוש חלקי', 2026, 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Mercury''s live English and Hebrew Milli-Q pages (lab water purification, Milli-Q IX/IQ/HX/SQ2) continue to present Mercury as Merck''s exclusive distributor for Milli-Q in Israel, so the lab-equipment channel is current. Sigma-Aldrich Israel Ltd. was not re-searched this round (search budget); its prior evidence is Merck''s own live offices page, which was not contradicted by anything found. Searched Sigma-Aldrich Israel/Rehovot generically, Merck/Milli-Q on Israeli distributor domains and sigmaaldrich.com/merckmillipore.com office pages. Sigma-Aldrich''s contact page lists ''Sigma-Aldrich Israel Ltd., an affiliate of Merck KGaA, Darmstadt, Germany'' at 3 Plaut St., Rehovot 7670603 (site self-assessment: operating since 1989, producing antibodies, primers and peptides), and Merck ISO certificates list a Jerusalem (Har Hotzvim) site, confirming Merck''s own Israeli entity. For lab equipment, Mercury Scientific & Industrial Products (part of Gadot since 2022) describes itself as the exclusive Israeli representative for Merck Milli-Q lab-water systems and distributor of Merck KGaA''s life-science and chemicals divisions, so Milli-Q is sold via Mercury rather than direct; this is self-reported on Mercury''s site and not independently confirmed by Merck.', '+972 8 948 4222 / +972 8 948 4100', 'isrcustserv@merckgroup.com', '3 Plaut St., Rehovot 7670603, Israel', 'https://www.sigmaaldrich.com/collections/offices', 'https://www.sigmaaldrich.com/collections/offices', NULL);
INSERT INTO products VALUES (835, 1, 'Milli-Q', 'laboratory ultrapure / pure water purification systems', 'prior', NULL);
INSERT INTO products VALUES (835, 2, 'Millipore filtration (Millex, Stericup, Mobius)', 'lab filtration and single-use bioprocess products', 'prior', NULL);
INSERT INTO products VALUES (835, 3, 'Sigma-Aldrich research chemicals', 'reagents, biochemicals and analytical standards', 'prior', NULL);
INSERT INTO israel_entities VALUES (835, 'Sigma-Aldrich Israel Ltd. (affiliate of Merck KGaA, Darmstadt)', NULL, 'subsidiary', 'Merck''s own Israeli entity: sales/customer contact for Israel and production sites in Rehovot (antibodies, primers, peptides; 3 Plaut St.) and Jerusalem (Har Hotzvim)', 'https://www.sigmaaldrich.com/IL/en', '+972-8-9484222 / +972-8-9484100', 'isrcustserv@merckgroup.com; isrtechserv@merckgroup.com', '3 Plaut St., Rehovot 7670603', 'https://b2b.sigmaaldrich.com/collections/offices', NULL, 'older_evidence', 'prior_research', NULL, 'https://www.sigmaaldrich.com/US/en/collections/offices');
INSERT INTO israel_entities VALUES (835, 'Mercury Scientific & Industrial Products Ltd. (Gadot group)', 'מרקורי מוצרי מדע ותעשייה (גדות מרקורי)', 'distributor', 'Merck Milli-Q laboratory water-purification systems (IX, IQ 7000, HX, CLX, SQ2 series) - live product pages describe Mercury as Merck''s exclusive Israeli distributor; Millipore filtration/MQuant lines per prior evidence', 'https://www.mercury-ltd.co.il', '+972 3-938-7164', NULL, '12 Ha''avoda St., P.O. Box 159, Rosh Ha''ayin', 'https://eng.mercury-ltd.co.il/about_us', 2026, 'current', 'prior_research', NULL, 'https://eng.mercury-ltd.co.il/lab_water_purification');
