INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (846, 'metrohm', 'Metrohm', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/metrohm', NULL, NULL, NULL, 'https://www.metrohm.com', 'prior', 'Switzerland', 'שווייץ', 'Herisau', 'Metrohm Foundation (Metrohm Stiftung)', 1943, 'Water & electrochemical analysis', 'Swiss scientific instrument company', 3200, 2024, 'company', 'prior', 640, 'CHF ~550 million (trade estimate; foundation-owned)', '2024 (estimate)', 'estimate', 'prior', 'mixed', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2025, '[אימות עדכניות 10/2026] Metrohm''s own news item ''New Metrohm distributor in Israel'' (July 2025) remains live on metrohm.com and names Israel Scientific Instruments Ltd. (ISI; founded 1971 as a Varian subsidiary, Steiner family since 1977) as the official distributor with immediate effect; Metrohm Middle East FZC (Sharjah) does not list Israel among its countries. ISI''s own site did not surface in snippets, so the recorded website is unverified. Metrohm''s own news item ''New Metrohm distributor in Israel'' (17 July 2025) states: ''Israel Scientific Instruments Ltd. (ISI) becomes the official distributor of Metrohm products and services in Israel'', effective immediately. Seen via the search-engine excerpt of the official page; the page itself could not be opened (host denied by egress proxy), so the previous distributor and ISI''s website were not captured. Metrohm Middle East FZC (Dubai) is the regional subsidiary for MENA; Israel is not among its listed authorised distributors. Hebrew search and ISI''s own site were not checked (search budget exhausted).', '+41 71 353 85 85', 'info@metrohm.com', 'Ionenstrasse, 9100 Herisau, Switzerland', 'https://www.metrohm.com/en/company/how-to-find-us.html', 'https://www.metrohm.com/en/Company-info.html', 'Q1925733');
