INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (898, 'nabertherm', 'Nabertherm', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Nabertherm', 'https://www.thomassci.com/browse-by/suppliers/nabertherm', NULL, NULL, NULL, 'https://nabertherm.com', 'prior', 'Germany', 'גרמניה', 'Lilienthal (near Bremen)', NULL, 1947, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', NULL, 600, 2026, 'company', 'prior', 72, 'EUR 65 million', 'FY2021', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: Nabertherm''s live World-Wide Sales page and a dedicated partner page (nabertherm.com/en/node/594, ''Electrotherm marketing1978 LTD'', Middle East region, industrial zone Migdal Haemek, sales email and phone) still name Electrotherm as its Israeli sales partner. Electrotherm''s own Nabertherm product pages were seen in the previous round and were not re-searched within the budget. A search restricted to nabertherm.com returned the official World-Wide Sales page whose snippet names Electrotherm Marketing 1978 Ltd, Migdal Haemek (sales@electrotherm.co.il), as the agent for Israel. A follow-up search restricted to electrotherm.co.il confirmed the distributor''s own Hebrew site (אלקטרוטרם) with Nabertherm product pages for melting furnaces (K 180/12), high-temperature furnaces, chamber/drying ovens (NA 1000/45 LS, 4500 WK), ceramic kilns, tube furnaces and the B400/C440/P470 controller documentation. Both the manufacturer''s locator and the distributor''s site therefore agree; the earlier round-1 locator snippet simply had not shown the Israel entry.', '+49 4298 922-0', 'contact@nabertherm.de', 'Bahnhofstraße 20, 28865 Lilienthal, Germany', 'https://nabertherm.com/en/contact/world-wide-sales', 'https://nabertherm.com/en/downloads/service-instructions', NULL);
INSERT INTO products VALUES (898, 1, 'L / LE / LT muffle furnaces', 'laboratory muffle furnaces up to 1,300 °C', 'prior', NULL);
INSERT INTO products VALUES (898, 2, 'RT / RS tube furnaces', 'compact and rotary tube furnaces', 'prior', NULL);
INSERT INTO products VALUES (898, 3, 'LHT / HTC high-temperature furnaces', 'chamber furnaces up to 1,800 °C', 'prior', NULL);
INSERT INTO israel_entities VALUES (898, 'Electrotherm Marketing 1978 Ltd.', 'אלקטרוטרם', 'distributor', 'Nabertherm sales partner for Israel per Nabertherm''s live World-Wide Sales page and dedicated partner page (Middle East region, I.Z. Ramat Gabriel, Migdal Haemek; sales@electrotherm.co.il); Electrotherm''s own site sells Nabertherm laboratory, high-temperature, melting, tube and drying furnaces and controllers (seen in the previous round)', 'https://www.electrotherm.co.il', '+972-77-866-0600', 'sales@electrotherm.co.il', 'Migdal HaEmek', NULL, 2026, 'current', 'prior_research', NULL, 'https://nabertherm.com/en/node/594');
