INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (900, 'nalgene', 'Nalgene', 'D', 'https://www.dutscher.com/search?initialFilters=brand:Nalgene', NULL, NULL, NULL, NULL, 'https://www.thermofisher.com', 'prior', 'USA', 'ארה"ב', 'Waltham, Massachusetts', NULL, 1956, 'Diversified analytical & life-science instruments', NULL, 125000, 2025, 'company', 'prior', 44560, 'USD 44.56 billion', 'FY2025', 'company', 'prior', 'reported', 'subsidiary', 'חברה-בת בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Re-verified on live pages: Rhenium (Applied Biosystems/Invitrogen/Thermo Scientific reagent, dPCR and centrifuge pages), Bargal (Orbitrap MS, combustion IC, ICP-MS/FTIR application notes), Danyel (Olink brand page) and Gamidor (Phadia ImmunoCAP/EliA pages) all currently market Thermo Fisher lines, and thermofisher.com''s Phenom desktop-SEM distributor page names Thermo Fisher Integrated Solutions as the Israel contact. thermofisher.com additionally lists three Israeli partners for industrial/portable lines (Iner-Tech, R.B.M., Madid), added as new. The Kiryat Shmona manufacturing site and the Airport City EM service location were not re-found in snippets (a Thermo Fisher careers page only confirms jobs in Israel generally); Gamidor''s microbiology scope (2025-26 letter) was not visible on its live pages, which show allergy/autoimmune diagnostics. Established from search-result evidence only (WebFetch and curl were blocked by the environment''s network policy, so manufacturer and distributor pages could not be opened). Searches run: ''"Thermo Fisher" Israel distributor'', ''"Thermo Fisher Scientific" Israel office Ltd'', ''"Thermo Fisher" ישראל נציג יבואן'', ''Rhenium Thermo Scientific Israel distributor'', ''Invitrogen Applied Biosystems Gibco Israel distributor'', ''"Thermo Fisher Integrated Solutions Israel"'', ''Bargal Analytical Instruments ... Thermo Scientific''. Picture: Thermo Fisher has its OWN Israeli presence (Thermo Fisher Israel Ltd. site in Kiryat Shmona with Israeli ISO certificates; an EM service location in Airport City, Lod; and a newly formed ''Thermo Fisher Integrated Solutions Israel'' subsidiary in Ra''anana that is hiring key-account managers and building a field-service team - i.e. a move toward direct sales for life-science products), PLUS division-specific Israeli distributors: Gamidor Diagnostics (non-exclusive distributor letter valid to Mar 2026, likely diagnostics/microbiology), Danyel Biotech (Olink), Rhenium (Life Technologies brands since 2011 - stale, may have been superseded by the new direct subsidiary) and Bargal (chromatography, 2018-2019 letter - stale). Fisher Scientific channel / Phadia (ImmunoCAP) / Thermo Scientific lab-equipment distributors in Israel were NOT established (the Phadia-locations page exists but could not be read). The exact registered names of the Israeli entities are unconfirmed (job ads say ''Thermo Fisher Integrated Solutions Israel'' / ''...Integrated Solutions Ltd'').', '+972 73 256 0860', NULL, 'Waltham, Massachusetts', 'https://www.thermofisher.com/store/v2/contact-us?enableChat=true', 'https://slimpages.startupim.com/company_page/thermo-fisher-scientific', NULL);
INSERT INTO products VALUES (900, 1, 'Thermo Scientific Orbitrap Astral', 'high-resolution Orbitrap LC-MS mass spectrometer', 'prior', NULL);
INSERT INTO products VALUES (900, 2, 'Applied Biosystems QuantStudio', 'real-time PCR (qPCR/dPCR) instrument family', 'prior', NULL);
INSERT INTO products VALUES (900, 3, 'Thermo Scientific Krios cryo-TEM', 'cryo-electron microscope for structural biology', 'prior', NULL);
INSERT INTO israel_entities VALUES (900, 'Thermo Fisher Integrated Solutions Israel Ltd.', 'תרמו פישר ישראל (רעננה)', 'subsidiary', 'direct life-science sales & field service organisation being built out 2025-26', 'https://www.thermofisher.com', '+972 8-940-8618', NULL, '5 Golda Meir St., Ness Ziona (also Airport City 1, Lod)', 'https://www.thermofisher.com/il/en/home.html', NULL, NULL, 'prior_research', NULL, 'https://www.thermofisher.com/il/en/home.html');
INSERT INTO israel_entities VALUES (900, 'Thermo Fisher Scientific Israel Ltd. (Kiryat Shmona)', 'תרמו פישר קריית שמונה', 'subsidiary', 'manufacturing / engineering site (ISO 9001/13485); not a sales channel', 'https://www.thermofisher.com', '+972 8-940-8618', NULL, '5 Golda Meir St., Ness Ziona (also Airport City 1, Lod)', 'https://www.thermofisher.com/il/en/home.html', NULL, NULL, 'prior_research', NULL, NULL);
INSERT INTO israel_entities VALUES (900, 'Rhenium Ltd.', 'רניום', 'distributor', 'Applied Biosystems / Invitrogen / Thermo Scientific products: live product pages for PowerTrack SYBR Green master mix, QuantStudio Absolute Q dPCR, SL 16 centrifuge, TaqMan/bioproduction reagents (Rhenium''s bioproduction page names Applied Biosystems as a partner)', 'https://www.rhenium.co.il', '+972 8-955-8888', NULL, '20 Hasatat St., P.O. Box 180, Modi''in 7171101', NULL, 2026, 'current', 'prior_research', NULL, 'https://rhenium.co.il/products/bioproduction');
INSERT INTO israel_entities VALUES (900, 'Gamidor Diagnostics (1984) Ltd.', 'גמידור דיאגנוסטיקה', 'distributor', 'Thermo Scientific / Phadia diagnostics: ImmunoCAP allergy and EliA autoimmune tests (Gamidor states EliA was consolidated under its distribution in Jan 2021 after earlier ImmunoCAP representation); the Mar 2025-Mar 2026 non-exclusive distributor letter for microbiology/diagnostics remains the prior evidence', 'https://www.gamidor.co.il', '+972-3-927-7277', 'info@gamidor.co.il', 'Shaham 32, Petach Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://gamidor.co.il/en/allergy/');
INSERT INTO israel_entities VALUES (900, 'Bargal Analytical Instruments Ltd.', 'ברגל', 'distributor', 'Thermo Scientific chromatography, mass spectrometry and spectroscopy: live product pages (Q Exactive UHMR Orbitrap MS, combustion IC system) and hosted application notes (ICP-MS, FTIR/OMNIC, lab automation); a 2018 Israeli government procurement attachment also shows Bargal as Thermo Fisher''s Israel distributor', 'https://www.bargal.co.il', '+972-3-979-6533', 'sales@bargal.co.il', '10 Shaked Street, Modi''in Industrial Park, Shoham 6085102', NULL, 2026, 'current', 'prior_research', NULL, 'https://bargal.co.il/product/q-exactive-uhmr-hybrid-quadrupole-orbitrap-ms-system/');
INSERT INTO israel_entities VALUES (900, 'Danyel Biotech Ltd.', 'דניאל ביוטק', 'distributor', 'Olink proteomics (a Thermo Fisher business): live Olink brand page on Danyel''s site', 'https://www.danyel.co.il', '1-800-711-911 (also +972 8-936-6066)', NULL, '8 Hamada St., Science Park, Rehovot 7670308', 'https://www.danyel.co.il/contact-us/', 2026, 'current', 'prior_research', NULL, 'https://www.danyel.co.il/olink/');
INSERT INTO israel_entities VALUES (900, 'Thermo Fisher Scientific – EM service location, Airport City', NULL, 'service', 'Thermo Fisher''s own Israeli sales/support organisation; thermofisher.com''s Phenom desktop-SEM distributor page names ''Thermo Fisher Integrated Solutions'' as the Israel contact (live page); a Thermo Fisher careers page lists jobs in Israel', 'https://www.thermofisher.com', '+972 8-940-8618', NULL, '5 Golda Meir St., Ness Ziona (also Airport City 1, Lod)', 'https://www.thermofisher.com/il/en/home.html', 2026, 'older_evidence', 'prior_research', NULL, 'https://www.thermofisher.com/us/en/home/electron-microscopy/products/desktop-scanning-electron-microscopes/phenom-distributors.html');
