INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (965, 'oxford instruments', 'Oxford Instruments America', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/oxford-instruments-america', NULL, NULL, NULL, 'https://www.oxinst.com', 'prior', 'UK', 'UK', 'Abingdon, Oxfordshire', NULL, 1959, 'Electron microscopy & X-ray / materials characterization', NULL, 2200, 2025, 'company', 'prior', 550, 'GBP 423.2 million', 'FY ended Mar-2026', 'company', 'prior', 'reported', 'unclear', 'לא ברור', 'partial', 'חיפוש חלקי', 2026, 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Changed from none_found to unclear with two leads, neither a confirmed current Oxford Instruments channel: (1) WITec (an Oxford Instruments company since 2021) appointed Advanced Technological Solutions Ltd. (ATSL), Kiryat Ata, as exclusive Israel distributor for SNOM/AFM/Raman in November 2012, with no later confirmation found; (2) Quantum Design Europe, which completed its acquisition of Oxford Instruments'' NanoScience division in January 2026 (now ''Quantum Design Oxford'') and lists Oxford Instruments Andor detectors and WITec Raman microscopes on its European country sites, serves Israel through a dedicated qd-europe.com/il site run from its ''Italy and Israel branch office'' in Rome. No source names an Israeli distributor for Andor cameras or NanoAnalysis EDS/EBSD, and the 21-domain Israeli distributor sweep returned only Quantum Design pages. Nothing credible found after four angles: the brand restricted to 43 Israeli distributor domains, a Hebrew importer/representative query, a search restricted to oxinst.com / andor.oxinst.com / nano.oxinst.com (Israel appears only as a country option in the Andor, Imaris and WITec contact forms; the WITec page says to contact HQ where no official representative exists), and an Israeli sole-supplier (ספק יחיד) tender query. No source seen names an Israeli distributor for Andor cameras, NanoAnalysis EDS/EBSD or WITec Raman; the Israeli channel may be direct from the UK/EU or via a company outside the domain list. Status remains none_found.', '+44 1865 393200', NULL, 'Tubney Woods, Abingdon, Oxfordshire OX13 5QX, UK', 'https://www.oxinst.com/contact-us', 'https://www.sharecast.com/scroll_3/equity/Oxford_Instruments/profile', NULL);
INSERT INTO products VALUES (965, 1, 'AZtec with Ultim Max (NanoAnalysis)', 'EDS/EBSD microanalysis systems for SEM/TEM', 'prior', NULL);
INSERT INTO products VALUES (965, 2, 'Andor iXon / Sona / Dragonfly', 'scientific EMCCD/sCMOS cameras & confocal imaging', 'prior', NULL);
INSERT INTO products VALUES (965, 3, 'PlasmaPro 100 (Plasma Technology)', 'plasma etch & deposition tools for semiconductors', 'prior', NULL);
INSERT INTO israel_entities VALUES (965, 'Advanced Technological Solutions Ltd. (ATSL)', NULL, 'distributor', 'WITec (an Oxford Instruments company since 2021) SNOM/AFM/Raman imaging systems - appointed exclusive distributor in Israel in November 2012 (Kiryat Ata); no later confirmation found, current status unknown', NULL, NULL, NULL, NULL, NULL, 2012, 'older_evidence', 'prior_research', NULL, 'https://www.analytica-world.com/en/news/140718/witec-appoints-new-distributor-in-israel.html');
INSERT INTO israel_entities VALUES (965, 'Quantum Design s.r.l. (Italy and Israel branch office, Rome) / Quantum Design Israel site', NULL, 'distributor', 'Quantum Design Europe serves Israel through a dedicated qd-europe.com/il site run from its ''Italy and Israel branch office'' in Rome (+39 06 5004204, italy@qd-europe.com). QD completed the acquisition of Oxford Instruments'' NanoScience division in January 2026 (now ''Quantum Design Oxford''), and QD Europe lists Oxford Instruments Andor detectors and WITec Raman microscopes on its European country sites; an Israel-specific Andor/WITec listing was not seen in snippets, so this is a lead, not a confirmed Oxford Instruments channel', 'https://qd-europe.com/il/en', NULL, NULL, NULL, NULL, 2026, 'new', 'prior_research', NULL, 'https://qd-europe.com/il/en/news/latest-updates/newsdetails/quantum-design-to-acquire-nanoscience-division-of-oxford-instruments--2384/');
