INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (988, 'phc corporation of north', 'PHC Corporation of North America', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/phc-corporation-of-north-america', NULL, NULL, NULL, 'https://www.phchd.com', 'prior', 'Japan', 'יפן', 'Tokyo (Minato-ku)', NULL, 1969, 'Lab refrigeration & cold storage', NULL, 8647, 2026, 'company', 'prior', 2442, 'JPY 364,403 million', 'FY Mar-2026', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Eldan''s live laboratory-instruments page still lists PHCbi incubators and freezers, so Eldan is a current Israeli channel. Lumitron''s live product pages show PHCBI as a brand tag next to its CO2 incubator shakers, a weak but live re-confirmation of its ''Our brands'' listing; no PHCbi product page on lumitron.co.il was seen. PHCbi''s own where-to-buy page was not re-searched within the budget (earlier check: Israel not visible). Searched generic queries, 27 Israeli distributor domains, phchd.com and enco.co.il. Eldan Electronic Instruments'' laboratory-instruments page lists PHCbi CO2/multigas incubators (incl. Cell-IQ) and PHCbi biomedical/pharmaceutical freezers alongside Hettich, so Eldan is a current Israeli channel; the Enco lead could not be confirmed (a search restricted to enco.co.il returned no PHC content). PHCbi''s own ''where to buy'' lists partners for APAC and PHC Europe B.V. for Europe but Israel was not visible, and it states it is not recruiting new distributors. Lumitron''s own ''Our brands'' page lists PHCbi among the brands it distributes in Israel (seen in a search excerpt).', '+81 3 5408 7280', NULL, '15F Dai-ichi Life Hibiya First, 1-13-2 Yurakucho, Chiyoda-ku, Tokyo 100-8403, Japan', 'https://www.phchd.com/global/forms/Input?form_id=%7BA1E4FD0D-9F27-4C4D-9FD1-7A057C9FE770%7D', 'https://www.phchd.com/global/news/2024/0315', NULL);
INSERT INTO products VALUES (988, 1, 'MDF-DU702VH VIP ECO', '-86C ultra-low temperature freezer', 'prior', NULL);
INSERT INTO products VALUES (988, 2, 'MCO-170AIC / MCO-230AIC IncuSafe', 'CO2 incubators with H2O2 decontamination', 'prior', NULL);
INSERT INTO products VALUES (988, 3, 'MPR / MBR series', 'pharmaceutical refrigerators and biomedical freezers', 'prior', NULL);
INSERT INTO israel_entities VALUES (988, 'Eldan Electronic Instruments', NULL, 'distributor', 'PHCbi CO2/multigas incubators and biomedical/pharmaceutical freezers - Eldan''s live laboratory-instruments page lists PHCbi alongside Hettich and Martin Christ', 'https://www.eldan.biz', '+972-3-937-1111', 'info@eldan.biz', '6 Hashiloach Street, P.O. Box 7641, Petach Tikva 49170', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.eldan.biz/laboratory-instruments/');
INSERT INTO israel_entities VALUES (988, 'Lumitron Ltd.', 'לומיטרון', 'distributor', 'PHCbi listed on Lumitron''s ''Our brands'' page (earlier record); this session ''PHCBI'' appears only as a brand tag on Lumitron''s live CO2-incubator-shaker product pages, so the relationship is re-confirmed weakly (brand mention, no PHCbi product page seen)', 'https://www.lumitron.co.il', '+972 52-525-6287', NULL, '17 Hamiflasim St., Petah Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.lumitron.co.il/our-brands-heb/?lang=en');
