INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1048, 'qiagen', 'Qiagen', 'T', NULL, 'https://www.thomassci.com/browse-by/suppliers/qiagen', NULL, NULL, NULL, 'https://www.qiagen.com', 'prior', 'Netherlands', 'הולנד', 'Venlo (statutory seat); operational HQ Hilden, Germany', NULL, 1984, 'Life-science instruments & reagents', NULL, 5654, 2025, 'company', 'prior', 2090, 'USD 2,090.0 million', 'FY2025', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Ilex Medical''s live catalogue (qPCR/dPCR, molecular biology, extraction, oncology, hematology, molecular lab services) re-confirms Ilex as the current QIAGEN channel. Eldan''s only QIAGEN mention remains the 2014 ILANIT page (about 12 years old); its live diagnostics-kits page does not list QIAGEN, so Eldan is kept as older evidence only. Lifegene was not re-searched. QIAGEN''s own site still does not name its Israeli partner in snippets. Searched QIAGEN Israel distributor/נציג/יבואן, Israeli distributor domains and qiagen.com. Ilex Medical''s own catalogue lists QIAGEN instruments and kits (QIAcuity, Rotor-Gene Q, QIAxcel, extraction, oncology), while Eldan''s site named QIAGEN as a represented manufacturer in 2014 and exhibited QIAGEN products in 2015-2016 - stale, so Eldan may no longer carry the line or may cover research-only products. QIAGEN''s own pages route Israel to ''a commercial partner in your country'' without naming one (a 2000 handbook named Westburg (Israel) Ltd., obsolete), and no QIAGEN Israeli subsidiary was found; QIAGEN''s acquisition of Israeli start-up Genoox is an R&D deal, not a sales channel. No source was seen for QIAsymphony/QIAstat-Dx specifically. Lifegene''s catalogue lists QIAGEN as supplier and brand for enzymes; Ilex Medical (per round 2) covers the QIAGEN instrument/kit line.', '+49 2103 29 12000', NULL, 'QIAGEN Str. 1, 40724 Hilden, Germany (operational HQ)', 'https://qiagen.com/ch/knowledge-and-support/contact-customer-support', 'https://www.biocompare.com/100425-QIAGEN/', NULL);
INSERT INTO products VALUES (1048, 1, 'QIAcube Connect', 'automated nucleic-acid extraction instrument', 'prior', NULL);
INSERT INTO products VALUES (1048, 2, 'QIAstat-Dx', 'syndromic molecular diagnostic panel system', 'prior', NULL);
INSERT INTO products VALUES (1048, 3, 'QuantiFERON-TB Gold Plus', 'interferon-gamma TB blood test', 'prior', NULL);
INSERT INTO israel_entities VALUES (1048, 'Ilex Medical Ltd.', NULL, 'distributor', 'QIAGEN molecular diagnostics and research: digital PCR and qPCR systems (QIAcuity, Rotor-Gene Q), nucleic-acid extraction, oncology and hematology assays, sample-to-result pathogen diagnostics; Ilex also offers molecular lab services run at QIAGEN''s laboratory in Germany - live Ilex catalogue pages', 'https://www.ilexmedical.com', '+972-3-9385500', NULL, '7 HaTnufa St., Petah Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.ilexmedical.com/catalog_products/qpcr-dpcr/');
INSERT INTO israel_entities VALUES (1048, 'Eldan Electronic Instruments (Neopharm group)', NULL, 'distributor', 'listed QIAGEN among the manufacturers it represents in Israel (life-science research) on a 2014 page and showed QIAGEN products at ISM/IIS meetings in 2015-2016; current status unconfirmed', 'https://eldan.biz', '+972-3-937-1111', 'info@eldan.biz', '6 Hashiloach Street, P.O. Box 7641, Petach Tikva 49170', NULL, 2014, 'older_evidence', 'prior_research', NULL, 'https://eldan.biz/?p=1052');
INSERT INTO israel_entities VALUES (1048, 'Lifegene Ltd.', 'לייפג''ין', 'distributor', 'https://www.lifegene.co.il', 'QIAGEN enzymes / OEM reagents sold through the Lifegene catalogue (not the QIAGEN instrument line)', '+972 8-644-4314', 'info@lifegene.co.il', '4 Ha''maayan St., Modi''in 7171101 (directory lists Modi''in; other sources say Mevo Horon – verify)', NULL, NULL, 'older_evidence', 'prior_research', NULL, 'https://www.lifegene.co.il/page_30153');
