INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1088, 'roche', 'Roche', 'Q', NULL, NULL, 'yes', NULL, NULL, 'https://diagnostics.roche.com', 'prior', 'Switzerland', 'שווייץ', 'Rotkreuz (division HQ) / Basel (group HQ)', 'Roche Holding AG', 1968, 'Clinical / IVD laboratory analyzers', NULL, 103249, 2024, 'parent', 'prior', 16205, 'CHF 13.85 billion', 'FY2025', 'segment', 'prior', 'reported', 'parent_subsidiary', 'דרך חברת-האם בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Roche''s own live pages confirm a direct diagnostics presence in Israel: the diagnostics safety-officers page lists Roche Diagnostics Israel at 6 Hacharash St., Hod Hasharon, the Roche Diagnostics locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address, and a May-2026 Roche careers posting for an Application Specialist (Molecular Solutions) in Hod Hasharon shows ongoing local activity. Gamidor (VENTANA tissue diagnostics) and Dyn (Accu-Chek) were re-confirmed on their own live pages, though those pages are dated. A 2025-2026 tender search (''Roche cobas Israel מכרז'') returned only global product news, so no new tender naming the cobas supplier was found. Searched ''"Roche Diagnostics" Israel distributor/נציג/יבואן'', Hebrew ''רוש דיאגנוסטיקה'', the 29 Israeli distributor domains, mr.gov.il tenders and roche.com/diagnostics.roche.com. Roche''s own diagnostics safety-officer page lists ''Roche Diagnostics Israel'' at 6 Hacharash St., Hod Hasharon, and Roche Diagnostics'' office-locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address; a Hod Hasharon job ad for a Point-of-Care Specialist selling IVD instruments and a Sheba Medical Center tender appendix listing a cobas e801 corroborate direct activity. No independent distributor for cobas/LightCycler was found; Gamidor (VENTANA tissue diagnostics) and Dyn (Diabetes Care) handle only narrow Roche Diagnostics sub-lines. Caveat: no tender award document naming the Israeli affiliate as the cobas supplier was seen.', '+972 9 973 7777', NULL, '6 Hacharash Street, Hod Hasharon 4524079, Israel', 'https://diagnostics.roche.com/me/en/contact-forms/contact-us-support.html', 'https://ichgcp.net/pharma-list/office/84-roche', NULL);
INSERT INTO products VALUES (1088, 1, 'cobas pro integrated solutions (c 503 / e 801)', 'high-throughput clinical chemistry and immunoassay analyzers', 'prior', NULL);
INSERT INTO products VALUES (1088, 2, 'cobas 6800 / 8800 and cobas 5800 Systems', 'automated PCR molecular diagnostics platforms', 'prior', NULL);
INSERT INTO products VALUES (1088, 3, 'LightCycler 480 / LightCycler PRO', 'real-time PCR instruments', 'prior', NULL);
INSERT INTO israel_entities VALUES (1088, 'Roche Pharmaceuticals (Israel) Ltd. - Diagnostics division ("Roche Diagnostics Israel")', NULL, 'subsidiary', 'Roche Diagnostics business in Israel (cobas core-lab/molecular, point-of-care IVD): Roche''s live safety-officers page lists ''Roche Diagnostics Israel'', 6 Hacharash Street, Hod Hasharon 4524079 with a local diagnostics safety officer (israel.lso-dia@roche.com); Roche Diagnostics'' live office-locations page lists Roche Pharmaceuticals (Israel) Ltd. at the same address (+972 9 973 7777); a Roche careers posting (ID 202605-111903, i.e. May 2026) for an Application Specialist - Molecular Solutions in Hod Hasharon shows an active local diagnostics team', 'https://www.roche.co.il', '+972-9-9737777', NULL, '6 Hacharash St., P.O. Box 3691, Hod Hasharon 4524079', NULL, 2026, 'current', 'prior_research', NULL, 'https://www.roche.com/solutions/diagnostics/safety-officers');
INSERT INTO israel_entities VALUES (1088, 'Gamidor Diagnostics', 'גאמידור דיאגנוסטיקה בע"מ', 'distributor', 'Roche Tissue Diagnostics only: Gamidor''s live Tissue Diagnostics page offers IHC, molecular ISH and histochemical staining on automated slide-preparation instruments from VENTANA (Roche); not cobas/LightCycler', 'https://gamidor.co.il', '+972-3-927-7277', 'info@gamidor.co.il', 'Shaham 32, Petach Tikva', NULL, 2026, 'current', 'prior_research', NULL, 'https://gamidor.co.il/en/tissue-diagnostics-2/');
INSERT INTO israel_entities VALUES (1088, 'Dyn Diagnostics', NULL, 'distributor', 'Roche Diabetes Care only: Dyn''s live Home Care page lists ACCU-CHEK among its brands and describes its partnership with Roche Diabetes Care (Germany); CoaguChek INR self-testing also mentioned; not laboratory analyzers', 'https://dyn.co.il', NULL, NULL, NULL, NULL, 2026, 'current', 'prior_research', NULL, 'https://dyn.co.il/home-care-en');
