INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1219, 'stuart', 'Stuart (Cole-Parmer)', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Stuart', 'https://www.thomassci.com/browse-by/suppliers/stuart-cole-parmer', NULL, NULL, NULL, 'https://www.antylia.com', 'prior', 'USA', 'ארה"ב', 'Vernon Hills, Illinois', 'Brookfield Business Partners & CDPQ (since May 2025)', 1955, 'Lab distribution & own-brand products', NULL, 2000, 2024, 'estimate', 'prior', 400, 'approx. USD 400 million (third-party directory estimate)', 'n/a (directory estimate seen Oct 2026)', 'estimate', 'prior', 'estimate', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Medent''s live product pages re-confirm it as an Israeli channel for Antylia''s Stuart brand (stirrers, hotplates, rotary evaporators, rotators, water stills) and add the Jenway brand (6305 UV/Vis spectrophotometer). Cole-Parmer''s own site names no Israeli distributor; its privacy policy only states that Antylia Scientific operates through direct fulfilment and distributors worldwide. The channel for the Cole-Parmer brand itself, Techne and Environmental Express remains unidentified. General search (''Cole-Parmer'' OR ''Antylia'' Israel distributor/נציג/יבואן) returned no Israeli entity and no Israel listing on Antylia/IDEX distributor pages (only Australia/NZ: John Morris; Italy). A search restricted to Israeli distributor domains found Medent (medent.co.il) listing Stuart-brand shakers, heated stirrers and water stills. No Israeli partner found for the Cole-Parmer brand itself, Jenway, Techne or Environmental Express; Masterflex is now Avantor and was not searched. Antylia''s own ''find a distributor'' page was not fetched (fetching blocked). Corporate note seen in snippet: Brookfield and CDPQ completed the acquisition of Antylia Scientific for approximately USD 1.3 billion (CDPQ news release).', '+1 800-323-4340', 'sales@antylia.com', '625 East Bunker Court, Vernon Hills, IL 60061, USA', NULL, 'https://www.thomasnet.com/company/cole-parmer-1148924/profile', NULL);
INSERT INTO products VALUES (1219, 1, 'Jenway spectrophotometers', 'UV/Vis and visible benchtop spectrophotometers', 'prior', NULL);
INSERT INTO products VALUES (1219, 2, 'Environmental Express HotBlock', 'sample digestion and prep for environmental testing', 'prior', NULL);
INSERT INTO products VALUES (1219, 3, 'Stuart / Techne benchtop equipment', 'stirrers, shakers, hotplates, dry blocks, thermal cyclers', 'prior', NULL);
INSERT INTO israel_entities VALUES (1219, 'Medent Scientific Instruments', 'מדנט מכשור מדעי', 'distributor', 'Stuart-brand general lab equipment (overhead and magnetic stirrers, SD300 digital hotplate, rotary evaporators, tube rotators, water stills) and Jenway-brand instruments (6305 UV/Vis spectrophotometer) on live Hebrew product pages - Stuart and Jenway are Antylia/Cole-Parmer brands; the Cole-Parmer brand itself was not seen', 'https://www.medent.co.il', '+972 72-395-0508 (sales); +972 8-683-6306 (service)', 'info@medent.co.il', '110 Mordei HaGetaot St., Beer Sheva 8420643', 'https://www.medent.co.il/scientific.equipment/%D7%A6%D7%95%D7%A8-%D7%A7%D7%A9%D7%A8/', 2026, 'current', 'prior_research', NULL, 'https://medent.co.il/scientific.equipment/product/%D7%A1%D7%A4%D7%A7%D7%98%D7%A8%D7%95%D7%A4%D7%95%D7%98%D7%95%D7%9E%D7%98%D7%A8-uvvis-%D7%9E%D7%A2%D7%91%D7%93%D7%AA%D7%99-%D7%93%D7%92%D7%9D-6305-%D7%AA%D7%95%D7%A6%D7%A8%D7%AA-jenway/');
