INSERT INTO suppliers (id, key, name, catalogs, dutscher_url, thomassci_url, quartzy, quartzy_new, own_brand_of, website, website_source, country, country_he, hq, parent, inception, industry, description, employees, employees_year, employees_scope, employees_source, revenue_usd_m, revenue_original, revenue_year, revenue_scope, revenue_source, size_basis, israel_presence, israel_presence_he, israel_check, israel_check_he, israel_evidence_year, israel_note, contact_phone, contact_email, contact_address, contact_url, contact_source, wikidata) VALUES (1327, 'velp', 'Velp', 'D+T', 'https://www.dutscher.com/search?initialFilters=brand:Velp', 'https://www.thomassci.com/browse-by/suppliers/velp', NULL, NULL, NULL, 'https://www.velp.com', 'prior', 'Italy', 'איטליה', 'Usmate Velate (Monza e Brianza)', NULL, 1983, 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', NULL, 200, 2024, 'estimate', 'prior', 25.6, 'EUR 23.26 million', 'FY2024', 'company', 'prior', 'reported', 'distributor', 'מפיץ/נציג בישראל', 'verified', 'אומת', 2026, '[אימות עדכניות 10/2026] Labotal''s live ''Represented Firms'' page lists VELP among the brands it represents, confirming the 2024 exclusivity statement on its VELP supplier page is still current. On the manufacturer side, VELP''s own distribution-awards page lists Israel among the countries where it has distributors but does not name the partner in the snippet. No other Israeli VELP channel (for general lab equipment such as stirrers) surfaced. Labotal (לבוטל) states on its own VELP supplier page that during 2024 it became the exclusive representative for VELP''s analytical product line in Israel (UDK Kjeldahl distillers, DKL digesters, NDA 702 Dumas nitrogen/protein analyser, fibre/fat extractors), and the BioFindly directory lists Labotal under VELP. The statement covers the analytical line only; VELP''s general lab equipment (stirrers, shakers, hotplates) may have a different Israeli channel, which was not found. velp.com was not checked (search budget).', '+39 039 628811', NULL, 'Via Stazione 16, 20865 Usmate (MB), Italy', 'https://velp.com/en-ww/where-we-are.aspx', 'https://velp.com/en-ww/where-we-are.aspx', NULL);
INSERT INTO products VALUES (1327, 1, 'UDK 169 / UDK 139', 'automatic Kjeldahl distillation and titration units', 'prior', NULL);
INSERT INTO products VALUES (1327, 2, 'NDA 702 Dumas analyzer', 'nitrogen/protein determination by combustion', 'prior', NULL);
INSERT INTO products VALUES (1327, 3, 'AREX-6 / ARE hotplate stirrers and DKL digesters', 'magnetic stirrers, hotplates and Kjeldahl digestion units', 'prior', NULL);
INSERT INTO israel_entities VALUES (1327, 'Labotal', 'לבוטל ציוד מדעי', 'distributor', 'VELP analytical line (UDK Kjeldahl distillers, DKL digesters, NDA 702 Dumas analyser, fibre/fat extractors, oxidation testers) - Labotal''s VELP supplier page states it became exclusive representative for VELP''s analytical line in Israel during 2024, and VELP is listed on Labotal''s live ''Represented Firms'' page; VELP''s own distribution-awards page lists Israel among its distributor countries without naming the firm', 'https://labotal.co.il', '+972 2-579-9222', 'Sales@labotal.co.il', 'Hashalom Rd., Abu Ghosh 9084500 (mail: Mevaseret Zion)', 'https://labotal.co.il/contact/', 2026, 'current', 'prior_research', NULL, 'https://labotal.co.il/firms/?lang=en');
